const DIALOG_FOCUSABLE_SELECTOR = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  'summary',
  '[tabindex]:not([tabindex="-1"])',
].join(",");

function useDialogAccessibility() {
  useEffect(() => {
    const triggers = new WeakMap<HTMLElement, HTMLElement>();
    const tracked = new Set<HTMLElement>();

    const focusableIn = (dialog: HTMLElement) => {
      const closedSections = Array.from(dialog.querySelectorAll<HTMLDetailsElement>("details:not([open])"));
      return Array.from(dialog.querySelectorAll<HTMLElement>(DIALOG_FOCUSABLE_SELECTOR))
        .filter((element) => !element.hidden && !element.closest("[inert]") && element.getAttribute("aria-hidden") !== "true"
          && element.getClientRects().length > 0 && getComputedStyle(element).visibility !== "hidden"
          && !closedSections.some((section) => section.contains(element) && !section.querySelector(":scope > summary")?.contains(element)));
    };
    const visibleDialogs = () => Array.from(document.querySelectorAll<HTMLElement>('[role="dialog"][aria-modal="true"]'))
      .filter((dialog) => dialog.getClientRects().length > 0);

    const syncDialogs = () => {
      const current = new Set(visibleDialogs());
      current.forEach((dialog) => {
        if (tracked.has(dialog)) return;
        const active = document.activeElement;
        if (active instanceof HTMLElement && !dialog.contains(active)) triggers.set(dialog, active);
        tracked.add(dialog);
        if (!dialog.hasAttribute("tabindex")) dialog.tabIndex = -1;
        window.requestAnimationFrame(() => {
          if (!dialog.isConnected || dialog.contains(document.activeElement)) return;
          (focusableIn(dialog)[0] || dialog).focus();
        });
      });
      tracked.forEach((dialog) => {
        if (current.has(dialog)) return;
        tracked.delete(dialog);
        const trigger = triggers.get(dialog);
        window.requestAnimationFrame(() => {
          if (trigger?.isConnected) trigger.focus();
        });
      });
    };

    const onKeyDown = (event: KeyboardEvent) => {
      const dialogs = visibleDialogs();
      const dialog = dialogs[dialogs.length - 1];
      if (!dialog) return;
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        const close = dialog.querySelector<HTMLButtonElement>('button[aria-label^="Close"], button[aria-label*="close" i], .modal-head button');
        if (close) close.click();
        else dialog.closest<HTMLElement>(".modal-backdrop")?.dispatchEvent(new globalThis.MouseEvent("mousedown", { bubbles: true }));
        return;
      }
      if (event.key !== "Tab") return;
      const focusable = focusableIn(dialog);
      if (!focusable.length) {
        event.preventDefault();
        dialog.focus();
        return;
      }
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (event.shiftKey && (document.activeElement === first || !dialog.contains(document.activeElement))) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && (document.activeElement === last || !dialog.contains(document.activeElement))) {
        event.preventDefault();
        first.focus();
      }
    };

    const observer = new MutationObserver(syncDialogs);
    observer.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ["role", "aria-modal", "hidden"] });
    window.addEventListener("keydown", onKeyDown, true);
    syncDialogs();
    return () => {
      observer.disconnect();
      window.removeEventListener("keydown", onKeyDown, true);
    };
  }, []);
}

