function RawResearchExportPanel({
  actorId,
  organ,
  onActorIdChange
}: {
  actorId: string;
  organ: OrganDetail;
  onActorIdChange: (value: string) => void;
}) {
  const trimmedActor = actorId.trim();
  const actor = trimmedActor ? { actorId: trimmedActor, authProvider: "navigator", subject: trimmedActor } satisfies NavigatorActor : undefined;
  const exportUrl = actor ? organResearchRawExportUrl(organ.id, actor, true) : "";
  return (
    <section className="panel-block raw-export-gate">
      <div>
        <h3>Raw JSON export</h3>
        <p>Downloads require trusted researcher permission: <code>navigator.raw_json_download</code>.</p>
      </div>
      <label>
        <span>Research actor ID</span>
        <input
          value={actorId}
          onChange={(event) => onActorIdChange(event.target.value)}
          placeholder="navigator:researcher:..."
        />
      </label>
      {actor ? (
        <a className="packet-download" href={exportUrl}>
          Download raw Research JSON
        </a>
      ) : (
        <button className="packet-download" type="button" disabled>
          Actor required
        </button>
      )}
      <small>
        The visible raw inspector remains explicit-click only. The download endpoint enforces actor permission on the server.
      </small>
    </section>
  );
}

function GeoreferencingReadinessPanel({ readiness }: { readiness: NonNullable<ResearchResponse["georeferencingReadiness"]> }) {
  const coordinateText = readiness.coordinates
    ? `${readiness.coordinates.lat}, ${readiness.coordinates.lon}`
    : "No coordinates";
  return (
    <section className="panel-block research-georef-panel">
      <div className="processor-readiness-head">
        <div>
          <h3>Georeferencing readiness</h3>
          <p>{readiness.message || (readiness.nextAction ? `Next suggested action: ${friendlyLabel(readiness.nextAction)}` : readiness.label)}</p>
        </div>
        <Pill tone={readiness.hasCoordinates ? "strong" : undefined}>{readiness.label}</Pill>
      </div>
      <div className="processor-readiness-grid">
        <ReadinessCard title="Location" status={readiness.status} details={[
          readiness.location || "Unknown location",
          readiness.country ? `Country: ${readiness.country}` : "Country unknown"
        ]} />
        <ReadinessCard title="Evidence" status={readiness.hasStructuredLocation ? "structured" : readiness.hasTextLocation ? "textual" : "missing"} details={[
          readiness.hasStructuredLocation ? "Structured location present" : "No structured location",
          readiness.hasTextLocation ? "Textual location present" : "No textual location"
        ]} />
        <ReadinessCard title="Coordinates" status={readiness.hasCoordinates ? "available" : "absent"} details={[
          coordinateText,
          readiness.nextAction ? `Next: ${friendlyLabel(readiness.nextAction)}` : "No action"
        ]} />
        <ReadinessCard title="Priority" status={readiness.priorityLabel || "unscored"} details={[
          typeof readiness.priority === "number" ? `Score: ${readiness.priority}` : "Score unavailable",
          readiness.structuredLocationFieldCount != null ? `${readiness.structuredLocationFieldCount} structured field(s)` : "Structured fields unknown"
        ]} />
      </div>
      {(readiness.priorityReasons ?? []).length > 0 && (
        <div className="georef-priority-reasons">
          {(readiness.priorityReasons ?? []).map((reason) => <span key={reason}>{reason}</span>)}
        </div>
      )}
      {readiness.evidence.length > 0 && (
        <div className="research-evidence-list">
          <h4>Location evidence</h4>
          {readiness.evidence.slice(0, 6).map((item) => (
            <article key={`${item.label}:${item.value}`}>
              <div>
                <strong>{item.label}</strong>
                <span>{item.value}</span>
              </div>
              <small>{item.source || "source evidence"}</small>
            </article>
          ))}
        </div>
      )}
      {readiness.evidencePacket && <GeoreferencingEvidencePacketPanel packet={readiness.evidencePacket} />}
      {readiness.coordinateCandidatePlan && <CoordinateCandidatePlanPanel plan={readiness.coordinateCandidatePlan} />}
      {readiness.spatialWorkflow && <SpatialWorkflowPanel workflow={readiness.spatialWorkflow} />}
      <div className="research-action-list">
        {readiness.actions.map((action) => (
          <article key={action.id} className={action.enabled ? "enabled" : "disabled"}>
            <div>
              <strong>{action.label}</strong>
              <span>{action.owner} · {action.mutates ? "mutating" : "read-only"}{action.requiresActor ? " · actor required" : ""}</span>
            </div>
            <Pill>{action.enabled ? friendlyLabel(action.status || "available") : "Unavailable"}</Pill>
          </article>
        ))}
      </div>
    </section>
  );
}

function CoordinateCandidatePlanPanel({ plan }: { plan: NonNullable<ResearchResponse["georeferencingReadiness"]>["coordinateCandidatePlan"] }) {
  const [handoffModalOpen, setHandoffModalOpen] = useState(false);
  if (!plan) return null;
  const coordinateText = plan.candidateCoordinate
    ? `${plan.candidateCoordinate.lat}, ${plan.candidateCoordinate.lon}`
    : "No coordinate candidate yet";
  const handoff = plan.processorHandoff;
  return (
    <div className="coordinate-candidate-plan">
      <div className="coordinate-plan-head">
        <div>
          <h4>{plan.label || "Coordinate candidate plan"}</h4>
          <p>{plan.guidance || "Coordinate candidates must pass review, canonical place linking, and spatial promotion before map publication."}</p>
        </div>
        <Pill>{friendlyLabel(plan.status || "unknown")}</Pill>
      </div>
      <div className="coordinate-plan-summary">
        <span>Candidate: {friendlyLabel(plan.candidateStatus || plan.candidateSource || "planned")}</span>
        <span>Owner: {plan.routeOwner || "Processor spatial enrichment"}</span>
        <span>Country: {plan.country || "Unknown"}</span>
        <span>{coordinateText}</span>
      </div>
      {plan.queryText && (
        <div className="georef-packet-query">
          <strong>{plan.queryText}</strong>
          <small>{plan.evidencePacketId || plan.sourceRecordId || plan.id}</small>
        </div>
      )}
      {(plan.confidenceInputs ?? []).length > 0 && (
        <div className="georef-priority-reasons">
          {(plan.confidenceInputs ?? []).map((input) => <span key={`${plan.id}:input:${input}`}>{input}</span>)}
        </div>
      )}
      {handoff && (
        <div className="processor-handoff-panel">
          <div>
            <strong>{handoff.label || "Processor handoff"}</strong>
            <Pill>{friendlyLabel(handoff.status || "planned")}</Pill>
          </div>
          <p>{handoff.reviewConstraint || "Processor must expose the durable spatial job contract before this handoff can run."}</p>
          <div className="processor-handoff-grid">
            <span>Module: {handoff.module}</span>
            <span>Job: {friendlyLabel(handoff.jobType)}</span>
            <span>Mode: {handoff.executionMode === "background" ? "Background run" : "Foreground job"}</span>
            <span>{handoff.requiresActor ? "Actor required" : "No actor required"} · {handoff.mutates ? "mutating" : "read-only"}</span>
            <span>Permission: {handoff.permissionLabel || friendlyLabel(handoff.permission || "pending")}</span>
            <span>{handoff.navigatorExecutable || handoff.enabled ? "Executable" : "Preview only"}</span>
          </div>
          <div className="processor-handoff-payload">
            {handoff.navigatorEndpoint && <span>{handoff.navigatorEndpoint}</span>}
            {handoff.idempotencyKey && <span>{handoff.idempotencyKey}</span>}
            {Object.keys(handoff.payloadTemplate ?? {}).slice(0, 8).map((key) => (
              <span key={`${handoff.id}:payload:${key}`}>{friendlyLabel(key)}</span>
            ))}
          </div>
          <button type="button" className="secondary georef-handoff-preview-button" onClick={() => setHandoffModalOpen(true)}>
            Open spatial handoff preview
          </button>
        </div>
      )}
      <div className="coordinate-quality-gates">
        {(plan.qualityGates ?? []).slice(0, 6).map((gate) => (
          <article key={gate.id}>
            <div>
              <strong>{gate.label}</strong>
              <span>{gate.owner}</span>
              {gate.detail && <small>{gate.detail}</small>}
            </div>
            <Pill>{friendlyLabel(gate.status || "unknown")}</Pill>
          </article>
        ))}
      </div>
      {plan.promotionBlocker && <p className="muted">{plan.promotionBlocker}</p>}
      {handoffModalOpen && handoff && (
        <GeoreferencingHandoffModal
          handoff={handoff}
          plan={plan}
          onClose={() => setHandoffModalOpen(false)}
        />
      )}
    </div>
  );
}

function GeoreferencingHandoffModal({
  handoff,
  onClose,
  plan
}: {
  handoff: NonNullable<NonNullable<ResearchResponse["georeferencingReadiness"]>["coordinateCandidatePlan"]>["processorHandoff"];
  onClose: () => void;
  plan: NonNullable<ResearchResponse["georeferencingReadiness"]>["coordinateCandidatePlan"];
}) {
  const payload = handoff?.payloadTemplate ?? {};
  const requestPreview = handoff?.requestPreview ?? {
    method: "POST",
    navigatorEndpoint: handoff?.navigatorEndpoint,
    headers: {
      "Idempotency-Key": handoff?.idempotencyKey || "",
      "X-Navigator-Actor-Id": "<required actor id>"
    },
    body: {
      job_type: handoff?.jobType,
      payload
    }
  };
  const payloadJson = JSON.stringify(payload, null, 2);
  const requestPreviewJson = JSON.stringify(requestPreview, null, 2);
  const checks = handoff?.confirmation?.checks ?? [];
  const gates = plan?.qualityGates ?? [];
  return (
    <div className="modal-backdrop" role="presentation" onMouseDown={onClose}>
      <div className="modal-panel georef-handoff-modal" role="dialog" aria-modal="true" aria-labelledby="georef-handoff-title" onMouseDown={(event) => event.stopPropagation()}>
        <div className="modal-head">
          <div>
            <h3 id="georef-handoff-title">{handoff?.confirmation?.title || handoff?.label || "Spatial geocoding handoff"}</h3>
            <p>{handoff?.owner || "Processor spatial enrichment"} · {handoff?.module}.{handoff?.jobType}</p>
          </div>
          <button type="button" className="icon-button" aria-label="Close spatial handoff preview" onClick={onClose}>
            <X size={18} aria-hidden="true" />
          </button>
        </div>
        <p className="modal-ownership">
          {handoff?.confirmation?.description || "Navigator previews this future Processor spatial job but does not create coordinate candidates directly."}
        </p>
        <div className="promotion-completion-metrics">
          <span>{handoff?.navigatorExecutable || handoff?.enabled ? "Executable" : "Preview only"}</span>
          <span>{handoff?.executionMode === "background" ? "Background run" : "Foreground job"}</span>
          <span>{handoff?.requiresActor ? "Actor required" : "Actor optional"}</span>
          <span>{handoff?.permission || "Review policy pending"}</span>
        </div>
        <div className="promotion-completion-section">
          <h4>Processor endpoint</h4>
          <div className="georef-handoff-endpoint">
            <span>{handoff?.navigatorEndpoint || "Endpoint not available"}</span>
            <span>{handoff?.idempotencyKey || "No idempotency key"}</span>
            <span>{handoff?.reviewConstraint || "Spatial contract is not executable yet."}</span>
          </div>
          <div className="georef-handoff-copy-actions">
            {handoff?.navigatorEndpoint && <CopyButton label="Copy endpoint" value={handoff.navigatorEndpoint} />}
            {handoff?.idempotencyKey && <CopyButton label="Copy idempotency key" value={handoff.idempotencyKey} />}
          </div>
        </div>
        <div className="promotion-completion-section">
          <h4>Payload preview</h4>
          <pre>{payloadJson}</pre>
          <div className="georef-handoff-copy-actions">
            <CopyButton label="Copy payload" value={payloadJson} />
          </div>
        </div>
        <div className="promotion-completion-section">
          <h4>Request preview</h4>
          <pre>{requestPreviewJson}</pre>
          <div className="georef-handoff-copy-actions">
            <CopyButton label="Copy request preview" value={requestPreviewJson} />
          </div>
        </div>
        <div className="promotion-completion-section">
          <h4>Spatial quality gates</h4>
          <div className="promotion-gate-list">
            {gates.length > 0 ? gates.map((gate) => (
              <article key={gate.id}>
                <div>
                  <strong>{gate.label}</strong>
                  <span>{gate.owner}</span>
                  {gate.detail && <small>{gate.detail}</small>}
                </div>
                <Pill tone={gate.status === "ready" || gate.status === "available" ? "strong" : undefined}>{friendlyLabel(gate.status || "unknown")}</Pill>
              </article>
            )) : <p className="muted">No spatial quality gates are available for this handoff yet.</p>}
          </div>
        </div>
        {checks.length > 0 && (
          <div className="promotion-completion-section">
            <h4>Confirmation checks</h4>
            <div className="promotion-post-checks">
              {checks.map((check) => <span key={check}>{check}</span>)}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

