function ComponentReviewModal({
  action,
  actionState,
  actor,
  actorId,
  component,
  evidence,
  onActorIdChange,
  onClose,
  onConfirm,
  permissionState
}: {
  action: ProcessorResearchAction;
  actionState?: ProcessorActionState;
  actor?: NavigatorActor;
  actorId: string;
  component: OrganComponent;
  evidence: NormalizerFactEvidence;
  onActorIdChange: (value: string) => void;
  onClose: () => void;
  onConfirm: () => void;
  permissionState: ProcessorActorPermissionState;
}) {
  const permissionCheck = action.permission ? permissionState.permissions[action.permission] : undefined;
  const permissionGate = processorPermissionGate(action, Boolean(actor), permissionCheck, permissionState.loading);
  const guardedHint = processorActionGuardHint(action, Boolean(actor), permissionCheck, permissionState.loading);
  const disabled = !action.enabled || !actor || permissionGate.blocked || Boolean(actionState?.loading || actionState?.refreshing);
  return (
    <div className="modal-backdrop" role="presentation" onMouseDown={onClose}>
      <div className="modal-panel component-review-modal" role="dialog" aria-modal="true" aria-labelledby="component-review-title" onMouseDown={(event) => event.stopPropagation()}>
        <div className="modal-head">
          <div>
            <h3 id="component-review-title">Review component candidate</h3>
            <p>{component.label} · {evidence.label}</p>
          </div>
          <button type="button" className="icon-button" onClick={onClose} aria-label="Close component review">
            <X size={18} />
          </button>
        </div>
        <p className="modal-ownership">
          Navigator previews this component decision and forwards it through the guarded review workflow for audit and later canonical promotion.
        </p>
        <div className="component-review-summary">
          <div>
            <span>Component</span>
            <strong>{component.label}</strong>
          </div>
          <div>
            <span>Source path</span>
            <strong>{component.sourcePath || "unknown source path"}</strong>
          </div>
          <div>
            <span>Candidate value</span>
            <strong>{evidence.value}</strong>
          </div>
          <div>
            <span>Candidate</span>
            <strong>{evidence.id || "unknown candidate"}</strong>
          </div>
        </div>
        <label className="component-review-actor">
          <span>Research actor ID</span>
          <input value={actorId} onChange={(event) => onActorIdChange(event.target.value)} placeholder="navigator:user:..." />
        </label>
        {action.permission && (
          <div className="component-review-permission">
            <PermissionGrantPill check={permissionCheck} hasActor={Boolean(actor)} loading={permissionState.loading} />
            <code>{action.permission}</code>
          </div>
        )}
        <ProcessorActionConfirmationPanel
          action={action}
          actor={actor}
          disabled={disabled}
          guardHint={guardedHint}
          onCancel={onClose}
          onConfirm={onConfirm}
          payload={processorActionPayload(action)}
        />
        {actionState?.refreshing && <small>Refreshing entity data after review decision.</small>}
        {actionState?.refreshedAt && !actionState.refreshing && <small>Entity data refreshed at {formatTimestamp(actionState.refreshedAt)}.</small>}
        {actionState?.error && <p className="research-run-inspection error">{actionState.error}</p>}
        {actionState?.result && <ProcessorActionResult actor={actor} result={actionState.result} />}
      </div>
    </div>
  );
}

function reviewItemScore(item: ProcessorReviewQueueItem): number | null {
  if (typeof item.score !== "number" || !Number.isFinite(item.score)) return null;
  return item.score > 1 ? item.score / 100 : item.score;
}

function reviewItemHasEnabledDecision(item: ProcessorReviewQueueItem): boolean {
  return (item.decisionOptions ?? []).some((option) => option.enabled);
}

function reviewItemHasApprovalDecision(item: ProcessorReviewQueueItem): boolean {
  return (item.decisionOptions ?? []).some((option) => {
    if (!option.enabled) return false;
    const label = `${option.id || ""} ${option.label || ""}`.toLowerCase();
    return /(approve|accept|confirm|link|merge|match)/.test(label) && !/(reject|deny|discard|dispute|split)/.test(label);
  });
}

function reviewItemIsHighSimilarity(item: ProcessorReviewQueueItem): boolean {
  const score = reviewItemScore(item);
  const signal = `${item.matchStatus || ""} ${item.reviewStatus || ""} ${item.candidateType || ""}`.toLowerCase();
  const negativeSignal = /(ambiguous|conflict|dispute|low|manual|uncertain|unknown|unmatched)/.test(signal);
  const positiveSignal = /(exact|high|strong|duplicate|same|match)/.test(signal);
  return reviewItemHasApprovalDecision(item) && !negativeSignal && (score == null ? positiveSignal : score >= 0.92);
}

function reviewItemApprovalDecisionLabels(item: ProcessorReviewQueueItem): string[] {
  return reviewItemApprovalOptions(item)
    .map((option) => option.label || friendlyLabel(option.id));
}

function reviewItemApprovalOptions(item: ProcessorReviewQueueItem): ProcessorReviewDecisionOption[] {
  return (item.decisionOptions ?? []).filter((option) => {
    if (!option.enabled) return false;
    const label = `${option.id || ""} ${option.label || ""}`.toLowerCase();
    return /(approve|accept|confirm|link|merge|match)/.test(label) && !/(reject|deny|discard|dispute|split)/.test(label);
  });
}

function reviewItemSimilarityReasons(item: ProcessorReviewQueueItem): string[] {
  const score = reviewItemScore(item);
  const approvalLabels = reviewItemApprovalDecisionLabels(item);
  const signal = `${item.matchStatus || ""} ${item.reviewStatus || ""} ${item.candidateType || ""}`.toLowerCase();
  const reasons = [
    score == null ? "No numeric score; lane depends on explicit match-status signal." : `Score ${Math.round(score * 100)}%${score >= 0.92 ? " meets the 92% threshold." : " is below the automatic high-similarity threshold."}`,
    approvalLabels.length > 0 ? `Approve-like decision available: ${approvalLabels.slice(0, 2).join(", ")}.` : "No approve-like decision is available.",
    /(exact|high|strong|duplicate|same|match)/.test(signal) ? "Match/status text includes a strong similarity signal." : "Match/status text does not add a strong similarity signal.",
    /(ambiguous|conflict|dispute|low|manual|uncertain|unknown|unmatched)/.test(signal) ? "Ambiguity or unmatched signal is present; manual inspection should take priority." : "No ambiguity, conflict, low-confidence, or unmatched signal is present.",
  ];
  return reasons;
}

function reviewSimilarityGroupKey(item: ProcessorReviewQueueItem): string {
  return [
    item.sourceRecordId || item.sourceTitle || "unknown-source",
    item.sessionId || "unknown-session",
    item.candidateKind || "candidate",
  ].join("|");
}

function reviewSimilarityGroupLabel(item: ProcessorReviewQueueItem): string {
  const sourceLabel = item.sourceTitle
    || item.sourceRecord?.primaryIdentifier?.value
    || item.sourceRecordId
    || "Unknown source";
  return `${sourceLabel} · ${staffTriageLabel(item.candidateKind || "candidate")}`;
}

function buildReviewSimilarityGroups(items: ProcessorReviewQueueItem[]): ReviewSimilarityGroup[] {
  const groups = new globalThis.Map<string, ProcessorReviewQueueItem[]>();
  items.forEach((item) => {
    const key = reviewSimilarityGroupKey(item);
    groups.set(key, [...(groups.get(key) ?? []), item]);
  });
  return Array.from(groups.entries())
    .map(([key, groupItems]) => {
      const first = groupItems[0];
      const scores = groupItems
        .map(reviewItemScore)
        .filter((score): score is number => typeof score === "number");
      const minScore = scores.length ? Math.min(...scores) : null;
      const maxScore = scores.length ? Math.max(...scores) : null;
      const sourceLabel = first.sourceTitle
        || first.sourceRecord?.primaryIdentifier?.value
        || first.sourceRecordId
        || "Unknown source";
      const sessionLabel = first.sessionId || "Unknown session";
      const candidateKind = staffTriageLabel(first.candidateKind || "candidate");
      const readyDecisionCount = groupItems.reduce((total, item) => total + (item.decisionOptions ?? []).filter((option) => option.enabled).length, 0);
      return {
        key,
        label: reviewSimilarityGroupLabel(first),
        sourceLabel,
        sessionLabel,
        candidateKind,
        count: groupItems.length,
        readyDecisionCount,
        scoreLabel: minScore == null || maxScore == null
          ? "Match-status based"
          : minScore === maxScore
            ? `${Math.round(maxScore * 100)}%`
            : `${Math.round(minScore * 100)}-${Math.round(maxScore * 100)}%`,
        reasons: [
          `${groupItems.length} high-similarity candidate${groupItems.length === 1 ? "" : "s"} from the same source/session/kind.`,
          `${readyDecisionCount} actor-gated decision${readyDecisionCount === 1 ? "" : "s"} available.`,
          minScore == null || maxScore == null ? "No numeric score range reported for this group." : `Score range: ${Math.round(minScore * 100)}-${Math.round(maxScore * 100)}%.`,
        ],
        items: groupItems,
      };
    })
    .sort((left, right) => right.count - left.count || left.sourceLabel.localeCompare(right.sourceLabel));
}

function buildReviewGroupApprovalPreview(group: ReviewSimilarityGroup, actor?: NavigatorActor): Record<string, unknown> {
  const requests = group.items.flatMap((item) => reviewItemApprovalOptions(item).map((option) => ({
    candidateId: item.candidateId,
    candidateLabel: item.label,
    candidateKind: item.candidateKind,
    score: reviewItemScore(item),
    decision: option.id,
    decisionLabel: option.label,
    permission: option.permission,
    navigatorEndpoint: "/api/processor/modules/normalizer/jobs",
    method: "POST",
    body: {
      job_type: option.jobType,
      payload: option.payloadTemplate ?? {},
    },
  })));
  return {
    mode: "preview_only_individual_review_candidate_jobs",
    batchExecutable: false,
    reason: "Processor batch review contract is not available; Navigator previews grouped work but keeps review_candidate decisions explicit and actor-confirmed.",
    actor: actor ? {
      actorId: actor.actorId,
      authProvider: actor.authProvider,
      subject: actor.subject,
    } : null,
    source: group.sourceLabel,
    session: group.sessionLabel,
    candidateKind: group.candidateKind,
    candidateCount: group.count,
    decisionCount: requests.length,
    scoreRange: group.scoreLabel,
    safeguards: [
      "No request is submitted by this preview.",
      "Each decision still uses Processor review_candidate.",
      "Actor identity and permission are checked before each mutation.",
      "Processor remains the system of record for review decisions and audit events.",
    ],
    requests,
  };
}

function buildReviewBatchHistoryEntry(
  result: ProcessorReviewBatchPlan,
  group: ReviewSimilarityGroup,
  actor: NavigatorActor
): ReviewBatchHistoryEntry {
  const recordedAt = result.batchExecution?.submittedAt || new Date().toISOString();
  const id = result.batchExecution?.batchRunId || `${result.batchPlanId || group.key}:${recordedAt}`;
  return {
    id,
    recordedAt,
    groupLabel: group.label,
    sourceLabel: group.sourceLabel,
    actorId: result.batchExecution?.actorId || actor.actorId,
    plan: result,
  };
}

function reviewBatchHistoryEntryFromReceipt(receipt: ProcessorReviewBatchReceipt): ReviewBatchHistoryEntry {
  const plan = receipt.receipt;
  const sourceLabel = receipt.sourceRecordId || plan.sourceRecordId || "review batch";
  const groupLabel = `${sourceLabel} · ${friendlyLabel(receipt.candidateKind || plan.candidateKind || "candidates")}`;
  return {
    id: receipt.batchRunId || plan.batchExecution?.batchRunId || plan.batchPlanId || `${sourceLabel}:${receipt.submittedAt || receipt.createdAt}`,
    recordedAt: receipt.submittedAt || receipt.createdAt || plan.batchExecution?.submittedAt || plan.generatedAt || new Date().toISOString(),
    groupLabel,
    sourceLabel,
    actorId: receipt.actorId || plan.batchExecution?.actorId || plan.auditTrail?.actorId || "unknown actor",
    plan,
  };
}

function reviewQueueModeLabel(mode: ReviewQueueMode): string {
  if (mode === "high_similarity") return "High-similarity lane";
  if (mode === "ready") return "Ready decisions";
  if (mode === "needs_inspection") return "Needs inspection";
  return "All visible candidates";
}

function reviewQueueModeSummary(mode: ReviewQueueMode): string {
  if (mode === "high_similarity") return "Strong score or match signal with an approve-like decision. Still requires actor confirmation.";
  if (mode === "ready") return "Candidates with at least one enabled Processor decision.";
  if (mode === "needs_inspection") return "Lower-confidence, ambiguous, or actionless candidates that should be inspected manually.";
  return "Everything returned by the current queue filters.";
}

type AutonomousSupersessionAction = "link_existing" | "create_provisional" | "abstain" | "reject" | "exception_review";
type AutonomousExceptionDraft = { action: AutonomousSupersessionAction; rationale: string; chosenCandidateId: string };

function AutonomousBootstrapDashboardPage({ canSupersede, onBack }: { canSupersede: boolean; onBack: () => void }) {
  const [dashboard, setDashboard] = useState<AutonomousBootstrapDashboard | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [drafts, setDrafts] = useState<Record<string, AutonomousExceptionDraft>>({});
  const [submitting, setSubmitting] = useState<Record<string, boolean>>({});
  const [messages, setMessages] = useState<Record<string, string>>({});
  function refresh() {
    setLoading(true);
    return fetchAutonomousBootstrapDashboard({ limit: 100 })
      .then((data) => {
        setDashboard(data);
        setError(null);
      })
      .catch((err: Error) => setError(err.message))
      .finally(() => setLoading(false));
  }

  useEffect(() => {
    refresh();
  }, []);

  function draftFor(item: AutonomousBootstrapException): AutonomousExceptionDraft {
    return drafts[item.exceptionId] ?? { action: "abstain", rationale: "", chosenCandidateId: item.chosenCandidateId ?? "" };
  }

  function updateDraft(item: AutonomousBootstrapException, patch: Partial<AutonomousExceptionDraft>) {
    setDrafts((current) => ({ ...current, [item.exceptionId]: { ...draftFor(item), ...patch } }));
  }

  function submitSupersession(item: AutonomousBootstrapException) {
    const draft = draftFor(item);
    if (!canSupersede || !item.decisionId || !item.observationId || !draft.rationale.trim()) return;
    setSubmitting((current) => ({ ...current, [item.exceptionId]: true }));
    setMessages((current) => ({ ...current, [item.exceptionId]: "" }));
    supersedeAutonomousBootstrapException(
      item.decisionId,
      {
        exception_kind: "resolution",
        observation_id: item.observationId,
        action: draft.action,
        chosen_candidate_id: draft.action === "link_existing" ? draft.chosenCandidateId.trim() || undefined : undefined,
        reason_codes: ["human_exception_adjudication"],
        rationale: draft.rationale.trim(),
      },
    )
      .then((result) => {
        if (!result.ok) throw new Error(result.error || "supersession_failed");
        setMessages((current) => ({ ...current, [item.exceptionId]: "Superseding Processor decision submitted." }));
        return refresh();
      })
      .catch((err: Error) => setMessages((current) => ({ ...current, [item.exceptionId]: err.message })))
      .finally(() => setSubmitting((current) => ({ ...current, [item.exceptionId]: false })));
  }

  const runCounts = dashboard?.metrics.batchRuns ?? {};
  const shardCounts = dashboard?.metrics.shards ?? {};
  const activeRuns = (runCounts.running ?? 0) + (runCounts.planned ?? 0) + (runCounts.paused ?? 0);
  const attentionShards = (shardCounts.failed ?? 0)
    + (shardCounts.retryable ?? 0)
    + (shardCounts.quarantined ?? 0);
  const exceptions = dashboard?.exceptionQueue ?? [];

  return (
    <section className="entity-route-page review-workbench-page" aria-labelledby="review-workbench-title">
      <button type="button" className="text-link-button evidence-route-back" onClick={onBack}>Back to catalog</button>
      <header className="entity-route-header">
        <div>
          <span className="eyebrow">Autonomous processing</span>
          <h2 id="review-workbench-title" tabIndex={-1}>Autonomous Bootstrap</h2>
          <p>Policy-authorized source processing, safe terminal exceptions, and Processor-owned projection receipts.</p>
        </div>
        <div className="review-workbench-filter-actions">
          <button type="button" className="secondary-button" onClick={() => refresh()} disabled={loading}>{loading ? "Refreshing…" : "Refresh"}</button>
          <a className="secondary-button" href={autonomousBootstrapProvenanceUrl("jsonld")}>PROV JSON-LD</a>
          <a className="secondary-button" href={autonomousBootstrapProvenanceUrl("ttl")}>PROV Turtle</a>
        </div>
      </header>

      {error && <p className="notice error">Autonomous bootstrap state unavailable: {error}</p>}
      {dashboard && !dashboard.schemaStatus.ready && (
        <p className="notice error">Required promoted tables are missing: {dashboard.schemaStatus.missingRequired.join(", ") || "unknown"}.</p>
      )}
      {dashboard && <p className="notice">{dashboard.guidance}</p>}

      <div className="metric-grid">
        <Metric label="Active policies" value={formatInteger(dashboard?.metrics.activePolicies ?? 0)} />
        <Metric label="Active batches" value={formatInteger(activeRuns)} />
        <Metric label="Attention shards" value={formatInteger(attentionShards)} />
        <Metric label="Exceptions" value={formatInteger(dashboard?.metrics.visibleExceptions ?? 0)} />
        <Metric label="Recent receipts" value={formatInteger(dashboard?.metrics.recentProjectionReceipts ?? 0)} />
      </div>

      <section className="review-workbench-command" aria-label="Active autonomous policy">
        <div>
          <strong>Git-pinned policy releases</strong>
          <span>Runtime agents cannot modify or activate policy dynamically.</span>
        </div>
        {(dashboard?.policy.active ?? []).length > 0 ? (dashboard?.policy.active ?? []).map((policy) => (
          <article key={policy.policyId}>
            <span>{policy.policyVersion}</span>
            <strong>{policy.policyId}</strong>
            <small><code>{policy.policyHash}</code> · valid from {formatTimestamp(policy.validFrom)}</small>
            {policy.releaseId && <small>Release {policy.releaseId} · scopes {(policy.activationScopes ?? []).join(", ") || "not reported"}</small>}
            {Object.keys(policy.releaseCommits ?? {}).length > 0 && (
              <small>{Object.entries(policy.releaseCommits ?? {}).map(([component, commit]) => `${component} ${commit.slice(0, 12)}`).join(" · ")}</small>
            )}
          </article>
        )) : <p>No active autonomous policy is visible.</p>}
      </section>

      <section>
        <h3>Recent runs</h3>
        <div className="review-workbench-list">
          {(dashboard?.runs ?? []).map((run) => (
            <article key={run.batchRunId}>
              <div className="review-workbench-item-head">
                <div><strong>{run.batchRunId}</strong><span>{friendlyLabel(run.state)} · {run.sourceProfileId || "unscoped profile"}</span></div>
                <code>{run.policyVersion}</code>
              </div>
              <div className="review-workbench-detail-grid">
                <div><span>Shards</span><strong>{run.importedShardCount}/{run.shardCount} imported</strong></div>
                <div><span>Attention</span><strong>{run.attentionShardCount}</strong></div>
                <div><span>Updated</span><strong>{formatTimestamp(run.updatedAt)}</strong></div>
                <div><span>Input fingerprint</span><code>{run.inputFingerprint}</code></div>
              </div>
            </article>
          ))}
          {!loading && (dashboard?.runs ?? []).length === 0 && <EmptyState icon={<Layers3 size={22} />} title="No bootstrap runs" body="No promoted Processor batch runs are visible yet." />}
        </div>
      </section>

      <section>
        <h3>Exception queue</h3>
        <p>Only quarantine, provisional, abstention, disagreement, policy denial, and other safe terminal outcomes appear here. They do not block the corpus.</p>
        <div className="review-workbench-list">
          {exceptions.map((item) => {
            const draft = draftFor(item);
            const canSubmit = Boolean(
              canSupersede
              && item.canSupersede
              && item.decisionId
              && item.observationId
              && draft.rationale.trim()
              && (draft.action !== "link_existing" || draft.chosenCandidateId.trim()),
            );
            return (
              <article key={item.exceptionId}>
                <div className="review-workbench-item-head">
                  <div>
                    <strong>{friendlyLabel(item.status)}</strong>
                    <span>{item.sourceRecordId || item.observationId || item.exceptionId}</span>
                  </div>
                  <code>{item.assuranceState ? friendlyLabel(item.assuranceState) : friendlyLabel(item.kind)}</code>
                </div>
                <div className="review-workbench-detail-grid">
                  <div><span>Owner</span><strong>{item.owner}</strong></div>
                  <div><span>Data state</span><strong>{item.status === "create_provisional" || item.status === "provisional" ? "Provisional" : "Uncertain"}</strong></div>
                  <div><span>Evidence state</span><strong>{item.sourceHash ? "Source-backed" : "Run/policy-backed"}</strong></div>
                  <div><span>Recorded</span><strong>{item.createdAt ? formatTimestamp(item.createdAt) : "Unknown"}</strong></div>
                  <div><span>Reasons</span><strong>{item.reasonCodes.length ? item.reasonCodes.map(friendlyLabel).join(", ") : "No reason code"}</strong></div>
                  {item.sourceHash && <div><span>Source hash</span><code>{item.sourceHash}</code></div>}
                  {item.batchShardId && <div><span>Shard</span><code>{item.batchShardId}</code></div>}
                  {item.batchRunId && <div><span>Batch run</span><code>{item.batchRunId}</code></div>}
                  {typeof item.attemptCount === "number" && <div><span>Attempts</span><strong>{formatInteger(item.attemptCount)}</strong></div>}
                  {item.policyRoute && <div><span>Selected policy</span><code>{item.policyRoute.resolutionPolicyId || item.policyRoute.relationshipPolicyId}</code></div>}
                  {item.policyRoute && <div><span>Exact selector</span><strong>{[item.policyRoute.sourceFamily, item.policyRoute.domainKey, item.policyRoute.entityKind || item.policyRoute.predicate].filter(Boolean).join(" · ")}</strong></div>}
                  {item.policyRoute?.kind === "resolution" && <div><span>Resolution thresholds</span><strong>block {item.policyRoute.blockingSimilarityThreshold ?? "—"} · link {item.policyRoute.linkThreshold ?? "—"} · margin {item.policyRoute.minimumMargin ?? "—"}</strong></div>}
                  {item.policyRoute?.kind === "resolution" && <div><span>Resolution versions</span><strong>{[item.policyRoute.resolverVersion, item.policyRoute.featureSetVersion, item.policyRoute.calibrationVersion].filter(Boolean).join(" · ")}</strong></div>}
                  {item.policyRoute?.kind === "relationship" && <div><span>Relationship precision</span><strong>minimum {item.policyRoute.minimumPrecision ?? "—"} · observed {item.policyRoute.precisionEvidence?.lowerBound ?? "—"}</strong></div>}
                  {item.policyRoute?.kind === "relationship" && <div><span>Relationship evidence</span><strong>{[item.policyRoute.classifierVersion, item.policyRoute.precisionEvidence?.calibrationVersion, item.policyRoute.precisionEvidence?.artifactRef].filter(Boolean).join(" · ")}</strong></div>}
                  {item.policyRoute?.precisionEvidence?.contentSha256 && <div><span>Calibration hash</span><code>{item.policyRoute.precisionEvidence.contentSha256}</code></div>}
                  {item.relationshipContext?.contextSha256 && <div><span>Relationship context</span><code>{item.relationshipContext.contextSha256}</code></div>}
                </div>
                {canSupersede && item.canSupersede && item.decisionId && item.observationId && (
                  <div className="processor-actor-gate review-workbench-gate">
                    <label><span>Superseding outcome</span><select value={draft.action} onChange={(event) => updateDraft(item, { action: event.target.value as AutonomousSupersessionAction })}><option value="abstain">Abstain</option><option value="create_provisional">Keep provisional</option><option value="exception_review">Keep exception</option><option value="reject">Reject</option><option value="link_existing">Link existing</option></select></label>
                    {draft.action === "link_existing" && <label><span>Chosen candidate ID</span><input value={draft.chosenCandidateId} onChange={(event) => updateDraft(item, { chosenCandidateId: event.target.value })} /></label>}
                    <label><span>Rationale</span><input value={draft.rationale} onChange={(event) => updateDraft(item, { rationale: event.target.value })} placeholder="Why this supersedes the prior decision" /></label>
                    <button type="button" onClick={() => submitSupersession(item)} disabled={!canSubmit || submitting[item.exceptionId]}>{submitting[item.exceptionId] ? "Submitting…" : "Append superseding decision"}</button>
                    {messages[item.exceptionId] && <small>{messages[item.exceptionId]}</small>}
                  </div>
                )}
              </article>
            );
          })}
          {!loading && exceptions.length === 0 && <EmptyState icon={<ShieldCheck size={22} />} title="No autonomous exceptions" body="All visible records reached policy-authorized or otherwise safe outcomes without requiring human work." />}
        </div>
      </section>

      <section>
        <h3>Recent projection receipts</h3>
        <div className="review-workbench-list">
          {(dashboard?.recentProjectionReceipts ?? []).map((receipt) => (
            <article key={receipt.receiptId}>
              <div className="review-workbench-item-head"><div><strong>{receipt.operation}</strong><span>{receipt.target.schema}.{receipt.target.table}:{receipt.target.id}</span></div><code>{receipt.policyVersion}</code></div>
              <div className="review-workbench-detail-grid"><div><span>Data state</span><strong>Canonical</strong></div><div><span>Receipt</span><code>{receipt.receiptId}</code></div><div><span>Policy execution</span><code>{receipt.policyExecutionId}</code></div><div><span>Actor</span><strong>{friendlyLabel(receipt.actorType)}</strong></div><div><span>Recorded</span><strong>{formatTimestamp(receipt.createdAt)}</strong></div></div>
            </article>
          ))}
        </div>
      </section>
    </section>
  );
}

function ProcessorReviewWorkbenchPage({
  actorId,
  onActorIdChange,
  onBack
}: {
  actorId: string;
  onActorIdChange: (value: string) => void;
  onBack: () => void;
}) {
  const [workbench, setWorkbench] = useState<ProcessorReviewWorkbench | null>(null);
  const [sourceRecordId, setSourceRecordId] = useState("");
  const [sessionId, setSessionId] = useState("");
  const [candidateKind, setCandidateKind] = useState("");
  const [country, setCountry] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionStates, setActionStates] = useState<Record<string, ProcessorActionState>>({});
  const [permissionState, setPermissionState] = useState<ProcessorActorPermissionState>({ loading: false, permissions: {} });
  const [pendingDecisionConfirmationId, setPendingDecisionConfirmationId] = useState<string | null>(null);
  const [queueMode, setQueueMode] = useState<ReviewQueueMode>(() => routeReviewQueueMode());
  const [selectedSimilarityGroupKey, setSelectedSimilarityGroupKey] = useState<string | null>(null);
  const [reviewBatchPlan, setReviewBatchPlan] = useState<ProcessorReviewBatchPlan | null>(null);
  const [reviewBatchLoading, setReviewBatchLoading] = useState(false);
  const [reviewBatchError, setReviewBatchError] = useState<string | null>(null);
  const [pendingBatchConfirmation, setPendingBatchConfirmation] = useState(false);
  const [reviewBatchHistory, setReviewBatchHistory] = useState<ReviewBatchHistoryEntry[]>([]);
  const [reviewBatchHistoryState, setReviewBatchHistoryState] = useState<{ loading: boolean; error?: string | null; durable?: boolean }>({ loading: false });

  const trimmedActor = actorId.trim();
  const actor = trimmedActor ? { actorId: trimmedActor, authProvider: "navigator", subject: trimmedActor } satisfies NavigatorActor : undefined;
  const permissionsToCheck = useMemo(
    () => Array.from(new Set((workbench?.items ?? [])
      .flatMap((item) => item.decisionOptions ?? [])
      .map((option) => option.permission)
      .filter((permission): permission is string => Boolean(permission)))),
    [workbench]
  );
  const permissionKey = permissionsToCheck.join("|");

  useEffect(() => {
    refreshWorkbench();
  }, []);

  useEffect(() => {
    const syncReviewLane = () => {
      const nextMode = routeReviewQueueMode();
      setQueueMode((current) => current === nextMode ? current : nextMode);
      if (nextMode !== "high_similarity") setSelectedSimilarityGroupKey(null);
    };
    window.addEventListener("popstate", syncReviewLane);
    window.addEventListener("hashchange", syncReviewLane);
    syncReviewLane();
    return () => {
      window.removeEventListener("popstate", syncReviewLane);
      window.removeEventListener("hashchange", syncReviewLane);
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    if (!trimmedActor || permissionsToCheck.length === 0) {
      setPermissionState({ loading: false, permissions: {} });
      return () => {
        cancelled = true;
      };
    }
    setPermissionState((current) => ({ ...current, actorId: trimmedActor, error: null, loading: true }));
    fetchProcessorActorPermissions(trimmedActor, permissionsToCheck)
      .then((response) => {
        if (cancelled) return;
        const permissions = response.permissions.reduce<Record<string, ProcessorActorPermissionCheck>>((acc, item) => {
          acc[item.permission] = item;
          return acc;
        }, {});
        setPermissionState({ actorId: response.actorId, loading: false, permissions });
      })
      .catch((err: Error) => {
        if (!cancelled) setPermissionState({ actorId: trimmedActor, error: err.message, loading: false, permissions: {} });
      });
    return () => {
      cancelled = true;
    };
  }, [permissionKey, trimmedActor]);

  useEffect(() => {
    let cancelled = false;
    if (!actor) {
      setReviewBatchHistoryState({ loading: false });
      return () => {
        cancelled = true;
      };
    }
    setReviewBatchHistoryState({ loading: true });
    fetchProcessorReviewBatchReceipts({ limit: 10 }, actor)
      .then((response) => {
        if (cancelled) return;
        const persisted = response.items.map(reviewBatchHistoryEntryFromReceipt);
        setReviewBatchHistory((current) => {
          const merged = new Map<string, ReviewBatchHistoryEntry>();
          [...current, ...persisted].forEach((entry) => merged.set(entry.id, entry));
          return Array.from(merged.values())
            .sort((left, right) => right.recordedAt.localeCompare(left.recordedAt))
            .slice(0, 10);
        });
        setReviewBatchHistoryState({ loading: false, durable: true });
      })
      .catch((err: Error) => {
        if (cancelled) return;
        setReviewBatchHistoryState({ loading: false, error: err.message, durable: false });
      });
    return () => {
      cancelled = true;
    };
  }, [actor?.actorId]);

  function refreshWorkbench(overrides: Partial<{ sourceRecordId: string; sessionId: string; candidateKind: string; country: string }> = {}) {
    setLoading(true);
    return fetchProcessorReviewWorkbench({
      limit: 80,
      sourceRecordId: (overrides.sourceRecordId ?? sourceRecordId).trim() || undefined,
      sessionId: (overrides.sessionId ?? sessionId).trim() || undefined,
      candidateKind: (overrides.candidateKind ?? candidateKind).trim() || undefined,
      country: (overrides.country ?? country).trim() || undefined,
    })
      .then((data) => {
        setWorkbench(data);
        setError(null);
        setReviewBatchPlan(null);
        setReviewBatchError(null);
        setPendingBatchConfirmation(false);
      })
      .catch((err: Error) => setError(err.message))
      .finally(() => setLoading(false));
  }

  function reviewDecisionAction(item: ProcessorReviewQueueItem, option: ProcessorReviewDecisionOption): ProcessorResearchAction {
    const payload = option.payloadTemplate ?? {};
    const candidateId = String(payload.candidate_id || item.candidateId || item.label);
    return {
      id: `global_review_queue:${candidateId}:${option.id}`,
      label: `${option.label} candidate`,
      module: option.module,
      jobType: option.jobType,
      mutates: option.mutates,
      permission: option.permission,
      permissionLabel: option.permissionLabel,
      requiresActor: option.requiresActor,
      roleHint: "Reviewer or operator with candidate review permission",
      confirmationRequired: option.confirmationRequired ?? true,
      confirmation: option.confirmation,
      enabled: option.enabled,
      status: option.status,
      payloadTemplate: payload
    };
  }

  function runReviewDecision(item: ProcessorReviewQueueItem, option: ProcessorReviewDecisionOption, confirmed = false) {
    const action = reviewDecisionAction(item, option);
    if (!action.enabled || actionStates[action.id]?.loading) return;
    if (action.mutates && action.confirmationRequired && !confirmed) {
      setPendingDecisionConfirmationId(action.id);
      return;
    }
    if (action.requiresActor && !actor) {
      setActionStates((current) => ({
        ...current,
        [action.id]: { loading: false, error: "Actor ID required for this review decision." }
      }));
      return;
    }
    const payload = action.payload ?? action.payloadTemplate ?? {};
    setPendingDecisionConfirmationId((current) => current === action.id ? null : current);
    setActionStates((current) => ({ ...current, [action.id]: { loading: true } }));
    runProcessorJob(action.module, { job_type: action.jobType, payload }, actor)
      .then((result) => {
        setActionStates((current) => ({
          ...current,
          [action.id]: { loading: false, refreshing: result.ok, result }
        }));
        if (result.ok) {
          return refreshWorkbench()
            .then(() => {
              setActionStates((current) => ({
                ...current,
                [action.id]: {
                  ...current[action.id],
                  loading: false,
                  refreshedAt: new Date().toISOString(),
                  refreshing: false
                }
              }));
            });
        }
        return undefined;
      })
      .catch((err: Error) => {
        setActionStates((current) => ({ ...current, [action.id]: { loading: false, error: err.message } }));
      });
  }

  const visibleItems = workbench?.items ?? [];
  const statusLabel = loading ? "Loading" : friendlyLabel(workbench?.status || "unavailable");
  const queueDecisionCount = visibleItems.reduce((total, item) => total + (item.decisionOptions ?? []).length, 0);
  const enabledDecisionCount = visibleItems.reduce(
    (total, item) => total + (item.decisionOptions ?? []).filter((option) => option.enabled).length,
    0
  );
  const permissionGrantedCount = permissionsToCheck.filter((permission) => permissionState.permissions[permission]?.allowed).length;
  const topSourceGroups = (workbench?.counts.bySource ?? []).slice(0, 3).map((item) => `${item.label}: ${item.count}`);
  const highSimilarityItems = visibleItems.filter(reviewItemIsHighSimilarity);
  const highSimilarityGroups = buildReviewSimilarityGroups(highSimilarityItems);
  const highSimilarityGroupKey = highSimilarityGroups.map((group) => group.key).join("||");
  const selectedSimilarityGroup = selectedSimilarityGroupKey
    ? highSimilarityGroups.find((group) => group.key === selectedSimilarityGroupKey) ?? null
    : null;
  const selectedGroupApprovalPreview = selectedSimilarityGroup ? buildReviewGroupApprovalPreview(selectedSimilarityGroup, actor) : null;
  const selectedGroupApprovalPreviewJson = selectedGroupApprovalPreview ? JSON.stringify(selectedGroupApprovalPreview, null, 2) : "";
  const selectedGroupCandidateIds = selectedSimilarityGroup?.items
    .map((item) => item.candidateId)
    .filter((candidateId): candidateId is string => Boolean(candidateId)) ?? [];
  const selectedGroupDecision = selectedSimilarityGroup?.items
    .map((item) => reviewItemApprovalOptions(item)[0]?.id)
    .find(Boolean) ?? "approved";
  const selectedGroupBatchRequest = selectedSimilarityGroup ? {
    candidate_ids: selectedGroupCandidateIds,
    decision: selectedGroupDecision,
    limit: 80,
    offset: workbench?.offset ?? 0,
    source_record_id: sourceRecordId.trim() || undefined,
    session_id: sessionId.trim() || undefined,
    candidate_kind: candidateKind.trim() || undefined,
    country: country.trim() || undefined,
  } : null;
  const selectedGroupBatchPlanJson = reviewBatchPlan ? JSON.stringify(reviewBatchPlan, null, 2) : "";
  const readyItems = visibleItems.filter(reviewItemHasEnabledDecision);
  const needsInspectionItems = visibleItems.filter((item) => !reviewItemIsHighSimilarity(item));
  const baseReviewItems = queueMode === "high_similarity"
    ? highSimilarityItems
    : queueMode === "ready"
      ? readyItems
      : queueMode === "needs_inspection"
        ? needsInspectionItems
        : visibleItems;
  const reviewItems = queueMode === "high_similarity" && selectedSimilarityGroup
    ? baseReviewItems.filter((item) => reviewSimilarityGroupKey(item) === selectedSimilarityGroup.key)
    : baseReviewItems;
  const laneButtons: Array<{ mode: ReviewQueueMode; count: number; detail: string }> = [
    { mode: "high_similarity", count: highSimilarityItems.length, detail: "Prioritize deterministic approval review" },
    { mode: "ready", count: readyItems.length, detail: "Actor-gated decisions available" },
    { mode: "needs_inspection", count: needsInspectionItems.length, detail: "Manual source inspection first" },
    { mode: "all", count: visibleItems.length, detail: "Current queue filters" },
  ];

  useEffect(() => {
    if (selectedSimilarityGroupKey && !highSimilarityGroups.some((group) => group.key === selectedSimilarityGroupKey)) {
      setSelectedSimilarityGroupKey(null);
    }
  }, [selectedSimilarityGroupKey, highSimilarityGroupKey]);

  useEffect(() => {
    let cancelled = false;
    setPendingBatchConfirmation(false);
    if (!actor || !selectedGroupBatchRequest || selectedGroupBatchRequest.candidate_ids.length < 2) {
      setReviewBatchPlan(null);
      setReviewBatchError(null);
      setReviewBatchLoading(false);
      return () => {
        cancelled = true;
      };
    }
    setReviewBatchLoading(true);
    setReviewBatchError(null);
    planProcessorReviewBatch(selectedGroupBatchRequest, actor)
      .then((plan) => {
        if (cancelled) return;
        setReviewBatchPlan(plan);
        setReviewBatchError(plan.ok ? null : plan.message || plan.error || "Batch plan is not executable.");
      })
      .catch((err: Error) => {
        if (cancelled) return;
        setReviewBatchPlan(null);
        setReviewBatchError(err.message);
      })
      .finally(() => {
        if (!cancelled) setReviewBatchLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [actor?.actorId, selectedSimilarityGroupKey, selectedGroupCandidateIds.join("|"), selectedGroupDecision]);

  function runSelectedGroupBatch(confirmed = false) {
    if (!actor || !selectedSimilarityGroup || !selectedGroupBatchRequest || !reviewBatchPlan?.ok || reviewBatchLoading) return;
    if (!confirmed) {
      setPendingBatchConfirmation(true);
      return;
    }
    setReviewBatchLoading(true);
    setReviewBatchError(null);
    planProcessorReviewBatch(
      {
        ...selectedGroupBatchRequest,
        execute: true,
        confirmation_phrase: reviewBatchPlan.confirmationPhrase || undefined,
      },
      actor
    )
      .then((result) => {
        setReviewBatchPlan(result);
        if (!result.ok) {
          setReviewBatchError(result.message || result.error || "Batch execution failed.");
          return undefined;
        }
        setPendingBatchConfirmation(false);
        setReviewBatchHistory((current) => [
          buildReviewBatchHistoryEntry(result, selectedSimilarityGroup, actor),
          ...current,
        ].slice(0, 5));
        return refreshWorkbench();
      })
      .catch((err: Error) => setReviewBatchError(err.message))
      .finally(() => setReviewBatchLoading(false));
  }

  function selectReviewQueueMode(mode: ReviewQueueMode) {
    window.history.pushState(null, "", reviewQueuePath(mode));
    setQueueMode(mode);
    if (mode !== "high_similarity") setSelectedSimilarityGroupKey(null);
  }

  const workbenchUnavailable = Boolean(workbench && (!workbench.ok || workbench.diagnostics?.reason === "processor_unavailable"));
  if (workbenchUnavailable) {
    return (
      <section className="entity-route-page review-workbench-page" aria-labelledby="review-workbench-title">
        <div className="route-page-header">
          <button type="button" className="ghost-button" onClick={onBack}>Back to catalog</button>
          <div>
            <p className="eyebrow">Moderation</p>
            <h2 id="review-workbench-title" tabIndex={-1}>Review Queue</h2>
            <p>Candidate review and approval workspace.</p>
          </div>
          <Pill>Unavailable</Pill>
        </div>
        <section className="review-service-unavailable" role="status">
          <AlertCircle size={28} aria-hidden="true" />
          <div>
            <h3>Review service unavailable</h3>
            <p>{reviewWorkbenchEmptyBody(workbench)}</p>
            <ul>
              <li>Public catalog and source pages remain available.</li>
              <li>Review decisions and queue metrics are temporarily paused.</li>
              <li>No empty-queue conclusion should be drawn from this state.</li>
            </ul>
            {error && <p className="error-text">{error}</p>}
            <div className="review-service-actions">
              <button type="button" onClick={() => refreshWorkbench()} disabled={loading}>{loading ? "Retrying…" : "Retry connection"}</button>
              <button type="button" className="ghost-button" onClick={onBack}>Continue in catalog</button>
            </div>
            <details>
              <summary>Technical diagnostics</summary>
              <dl>
                <div><dt>Reason</dt><dd>{staffTriageLabel(workbench?.diagnostics?.reason || "unavailable")}</dd></div>
                <div><dt>Service endpoint</dt><dd><code>{workbench?.diagnostics?.processorUrl || "Not configured"}</code></dd></div>
                <div><dt>Last successful connection</dt><dd>Not reported</dd></div>
              </dl>
            </details>
          </div>
        </section>
      </section>
    );
  }

  return (
    <section className="entity-route-page review-workbench-page" aria-labelledby="review-workbench-title">
      <div className="route-page-header">
        <button type="button" className="ghost-button" onClick={onBack}>Back to catalog</button>
        <div>
          <p className="eyebrow">Research</p>
          <h2 id="review-workbench-title" tabIndex={-1}>Review Queue</h2>
          <p>Review candidate matches and record moderator decisions with actor-gated audit trails.</p>
        </div>
        <Pill tone={workbench?.ok ? "strong" : undefined}>{statusLabel}</Pill>
      </div>

      <div className="processor-actor-gate review-workbench-gate">
        <div>
          <strong>Moderator session</strong>
          <span>{actor ? `Actor: ${actor.actorId}` : "Actor required before review decisions can run."}</span>
          {permissionState.loading && <span>Checking permission grants.</span>}
          {permissionState.error && <span>Permission check unavailable: {permissionState.error}</span>}
        </div>
        <label>
          <span>Reviewer actor ID</span>
          <input value={actorId} onChange={(event) => onActorIdChange(event.target.value)} placeholder="navigator:user:processor-dev" />
        </label>
      </div>
      <section className="review-workbench-command" aria-label="Review queue triage">
        <ReadinessCard
          title="Visible candidates"
          status={String(workbench?.counts.visible ?? 0)}
          details={[
            loading ? "Refreshing queue" : `${visibleItems.length} loaded`,
            workbench?.offset ? `Page starts after ${workbench.offset}` : "First page",
          ]}
        />
        <ReadinessCard
          title="Ready decisions"
          status={String(enabledDecisionCount)}
          details={[
            `${queueDecisionCount} available action${queueDecisionCount === 1 ? "" : "s"}`,
            actor ? "Actor set" : "Actor required",
          ]}
        />
        <ReadinessCard
          title="High similarity"
          status={String(highSimilarityItems.length)}
          details={[
            "Deterministic lane",
            "Explicit approval still required",
          ]}
        />
        <ReadinessCard
          title="Permission grants"
          status={permissionState.loading ? "Checking" : `${permissionGrantedCount}/${permissionsToCheck.length}`}
          details={permissionsToCheck.length > 0 ? permissionsToCheck.slice(0, 2).map(staffTriageLabel) : ["No guarded decisions visible"]}
        />
        <ReadinessCard
          title="Top sources"
          status={String(workbench?.counts.bySource.length ?? 0)}
          details={topSourceGroups.length > 0 ? topSourceGroups : ["No source groups visible"]}
        />
      </section>
      <section className="review-workbench-lanes" aria-label="Review triage lanes">
        <div>
          <strong>{reviewQueueModeLabel(queueMode)}</strong>
          <span>{reviewQueueModeSummary(queueMode)}</span>
        </div>
        <div className="review-workbench-lane-buttons">
          <button
            type="button"
            className={candidateKind === "event" ? "selected" : ""}
            onClick={() => {
              setCandidateKind("event");
              refreshWorkbench({ candidateKind: "event" });
            }}
          >
            <strong>{(workbench?.counts.byCandidateKind ?? []).find((item) => item.value === "event")?.count ?? 0}</strong>
            <span>Events</span>
            <small>Identity, facets, evidence, and provenance</small>
          </button>
          {laneButtons.map((item) => (
            <button
              type="button"
              key={item.mode}
              className={queueMode === item.mode ? "selected" : ""}
              onClick={() => {
                selectReviewQueueMode(item.mode);
              }}
            >
              <strong>{item.count}</strong>
              <span>{reviewQueueModeLabel(item.mode)}</span>
              <small>{item.detail}</small>
            </button>
          ))}
        </div>
      </section>
      {workbench?.diagnostics && (
        <section className={`review-workbench-state ${reviewWorkbenchStatusTone(workbench)}`} aria-label="Review queue runtime state">
          <div>
            <strong>{reviewWorkbenchStatusTitle(workbench)}</strong>
            <span>{reviewWorkbenchStatusBody(workbench)}</span>
          </div>
          <div className="review-workbench-state-grid">
            <span><strong>{staffTriageLabel(workbench.diagnostics.reason)}</strong> reason</span>
            <span><strong>{workbench.diagnostics.processorUrl || "Not configured"}</strong> Processor URL</span>
            <span><strong>{workbench.diagnostics.returnedItems ?? 0}</strong> returned</span>
            <span><strong>{workbench.diagnostics.visibleItems ?? workbench.counts.visible}</strong> visible</span>
          </div>
        </section>
      )}
      {highSimilarityGroups.length > 0 && (
        <section className="review-similarity-groups" aria-label="High-similarity source groups">
          <div className="section-heading">
            <h3>High-similarity groups</h3>
            <span>Grouped by source, session, and candidate kind. Selecting a group only filters the lane; decisions remain explicit.</span>
          </div>
          <div className="review-similarity-group-grid">
            {highSimilarityGroups.slice(0, 8).map((group) => (
              <button
                type="button"
                key={group.key}
                className={selectedSimilarityGroupKey === group.key ? "selected" : ""}
                onClick={() => {
                  selectReviewQueueMode("high_similarity");
                  setSelectedSimilarityGroupKey((current) => current === group.key ? null : group.key);
                }}
              >
                <strong>{group.label}</strong>
                <span>{group.count} candidate{group.count === 1 ? "" : "s"} · {group.readyDecisionCount} decisions · {group.scoreLabel}</span>
                <small>{group.sessionLabel}</small>
              </button>
            ))}
          </div>
          {selectedSimilarityGroup && (
            <div className="review-similarity-group-summary">
              <strong>{selectedSimilarityGroup.label}</strong>
              <div>
                {selectedSimilarityGroup.reasons.map((reason) => <span key={reason}>{reason}</span>)}
              </div>
              {selectedGroupApprovalPreview && (
                <details className="review-group-preview">
                  <summary>Group approval batch</summary>
                  <p>
                    Backend-validated grouped plan. Execution still submits individual Processor review_candidate jobs with actor headers and an exact confirmation phrase.
                  </p>
                  <div className="review-group-preview-actions">
                    <CopyButton label="Copy local preview" value={selectedGroupApprovalPreviewJson} />
                    {selectedGroupBatchPlanJson && <CopyButton label="Copy batch plan" value={selectedGroupBatchPlanJson} />}
                    <CopyButton label="Copy source" value={selectedSimilarityGroup.sourceLabel} />
                    {actor ? <span>Actor: {actor.actorId}</span> : <span>Actor required before any listed decision can run.</span>}
                  </div>
                  {reviewBatchLoading && <p>Checking current queue, actor permission, and batch safeguards...</p>}
                  {reviewBatchError && <p className="inline-error">{reviewBatchError}</p>}
                  {reviewBatchPlan?.ok && (
                    <div className="review-group-batch-summary">
                      <span>{reviewBatchPlan.candidateCount ?? selectedGroupCandidateIds.length} candidates</span>
                      <span>{reviewBatchPlan.decisionCount ?? selectedGroupCandidateIds.length} decisions</span>
                      {reviewBatchPlan.scoreRange && <span>{reviewBatchPlan.scoreRange}</span>}
                      <span>{reviewBatchPlan.executed ? "Submitted" : "Ready for explicit approval"}</span>
                    </div>
                  )}
                  {reviewBatchPlan?.ok && !reviewBatchPlan.executed && (
                    <div className="review-group-preview-actions">
                      <button
                        type="button"
                        className="primary-button"
                        disabled={!actor || reviewBatchLoading}
                        onClick={() => runSelectedGroupBatch(false)}
                      >
                        Prepare batch approval
                      </button>
                      {pendingBatchConfirmation && (
                        <>
                          <span>Confirm: {reviewBatchPlan.confirmationPhrase}</span>
                          <button
                            type="button"
                            className="danger-button"
                            disabled={reviewBatchLoading}
                            onClick={() => runSelectedGroupBatch(true)}
                          >
                            Execute grouped approval
                          </button>
                        </>
                      )}
                    </div>
                  )}
                  {reviewBatchPlan?.executed && (
                    <p>{reviewBatchPlan.acceptedCount ?? 0} submitted, {reviewBatchPlan.failedCount ?? 0} failed. Refreshing queue state.</p>
                  )}
                  <pre>{selectedGroupBatchPlanJson || selectedGroupApprovalPreviewJson}</pre>
                </details>
              )}
              <button type="button" className="ghost-button" onClick={() => setSelectedSimilarityGroupKey(null)}>Show all high-similarity candidates</button>
            </div>
          )}
        </section>
      )}
      {reviewBatchHistory.length > 0 && (
        <section className="review-batch-history" aria-label="Recent grouped review submissions">
          <div className="section-heading">
            <div>
              <h3>Recent grouped submissions</h3>
              <span>{reviewBatchHistoryState.durable ? "Persisted Navigator receipts for Processor review_candidate batches." : "Session-local execution receipts from Processor review_candidate batches."}</span>
            </div>
            <CopyButton label="Copy latest receipt" value={JSON.stringify(reviewBatchHistory[0].plan, null, 2)} />
          </div>
          {reviewBatchHistoryState.error && <p className="inline-error">Persisted receipt history unavailable: {reviewBatchHistoryState.error}</p>}
          <div className="review-batch-history-list">
            {reviewBatchHistory.map((entry) => {
              const receiptJson = JSON.stringify(entry.plan, null, 2);
              const execution = entry.plan.batchExecution;
              const checks = entry.plan.postActionChecks ?? [];
              const results = entry.plan.results ?? [];
              return (
                <details key={entry.id} className="review-batch-history-entry">
                  <summary>
                    <strong>{entry.groupLabel}</strong>
                    <span>{entry.plan.acceptedCount ?? 0} submitted · {entry.plan.failedCount ?? 0} failed · {friendlyLabel(execution?.status || entry.plan.status || "submitted")}</span>
                  </summary>
                  <div className="review-batch-history-grid">
                    <span>Actor: {entry.actorId}</span>
                    <span>Source: {entry.sourceLabel}</span>
                    {entry.plan.batchPlanId && <span>Plan: {entry.plan.batchPlanId}</span>}
                    {execution?.batchRunId && <span>Run: {execution.batchRunId}</span>}
                    <span>{execution?.submittedAt || entry.recordedAt}</span>
                    <span>{execution?.systemOfRecord || entry.plan.auditTrail?.systemOfRecord || "Processor"} record</span>
                    <span>{entry.plan.receiptPersistence?.ok || reviewBatchHistoryState.durable ? "Persisted receipt" : "Session receipt"}</span>
                  </div>
                  {checks.length > 0 && (
                    <div className="review-batch-checks">
                      {checks.map((check) => <span key={check}>{check}</span>)}
                    </div>
                  )}
                  {results.length > 0 && (
                    <div className="review-batch-result-list">
                      {results.slice(0, 8).map((item, index) => (
                        <span key={`${entry.id}:${String(item.candidateId || index)}`}>
                          {String(item.candidateId || `candidate ${index + 1}`)} · {item.ok ? "accepted" : "failed"}
                        </span>
                      ))}
                      {results.length > 8 && <span>{results.length - 8} more results</span>}
                    </div>
                  )}
                  <div className="review-group-preview-actions">
                    <CopyButton label="Copy receipt" value={receiptJson} />
                    {entry.plan.batchExecution?.batchRunId && <CopyButton label="Copy run ID" value={entry.plan.batchExecution.batchRunId} />}
                  </div>
                </details>
              );
            })}
          </div>
        </section>
      )}
      {actor && permissionsToCheck.length > 0 && (
        <ActorPermissionDetails
          actorId={actor.actorId}
          loading={permissionState.loading}
          permissions={permissionsToCheck.map((permission) => permissionState.permissions[permission]).filter(Boolean)}
        />
      )}

      <form
        className="review-workbench-filters"
        onSubmit={(event) => {
          event.preventDefault();
          refreshWorkbench();
        }}
      >
        <label>
          <span>Source record</span>
          <input value={sourceRecordId} onChange={(event) => setSourceRecordId(event.target.value)} placeholder="sr:..." />
        </label>
        <label>
          <span>Session</span>
          <input value={sessionId} onChange={(event) => setSessionId(event.target.value)} placeholder="norm_..." />
        </label>
        <label>
          <span>Candidate kind</span>
          <select value={candidateKind} onChange={(event) => setCandidateKind(event.target.value)}>
            <option value="">All kinds</option>
            {(workbench?.counts.byCandidateKind ?? []).map((item) => (
              <option key={item.value} value={item.value}>{item.label}</option>
            ))}
            {["event", "entity", "assertion", "relation", "match"].filter((value) => !(workbench?.counts.byCandidateKind ?? []).some((item) => item.value === value)).map((value) => (
              <option key={value} value={value}>{friendlyLabel(value)}</option>
            ))}
          </select>
        </label>
        <label>
          <span>Country</span>
          <select value={country} onChange={(event) => setCountry(event.target.value)}>
            <option value="">All countries</option>
            {(workbench?.counts.byCountry ?? []).map((item) => (
              <option key={item.value} value={item.value}>{item.label}</option>
            ))}
          </select>
        </label>
        <div className="review-workbench-filter-actions">
          <button type="submit" disabled={loading}>{loading ? "Loading" : "Refresh"}</button>
          <button
            type="button"
            className="ghost-button"
            onClick={() => {
              setSourceRecordId("");
              setSessionId("");
              setCandidateKind("");
              setCountry("");
              refreshWorkbench({ sourceRecordId: "", sessionId: "", candidateKind: "", country: "" });
            }}
          >
            Clear
          </button>
        </div>
      </form>

      {error && <p className="error-text">{error}</p>}
      {workbench && (
        <>
          <div className="review-workbench-groups">
            <GroupPills label="Candidate kind" items={workbench.counts.byCandidateKind} onSelect={(value) => { setCandidateKind(value); refreshWorkbench({ candidateKind: value }); }} />
            <GroupPills label="Country" items={workbench.counts.byCountry} onSelect={(value) => { setCountry(value === "Unknown" ? "" : value); refreshWorkbench({ country: value === "Unknown" ? "" : value }); }} />
          </div>
        </>
      )}

      <div className="review-workbench-list">
        {reviewItems.length > 0 ? reviewItems.map((item) => (
          <article key={item.candidateId || `${item.sessionId}:${item.label}:${item.sourcePath}`}>
            <div className="review-workbench-item-head">
              <div>
                <strong>{item.label}</strong>
                <span>{staffTriageLabel(item.candidateKind || "candidate")} · {staffTriageLabel(item.reviewStatus || "unknown")}{item.matchStatus ? ` · ${staffTriageLabel(item.matchStatus)}` : ""}</span>
                {item.sourceTitle && <span>{item.sourceTitle}{item.country ? ` · ${item.country}` : ""}</span>}
              </div>
              <div className="review-workbench-item-actions">
                {reviewItemIsHighSimilarity(item) && <Pill tone="strong">High similarity</Pill>}
                {item.sourceRecordId && <a href={`/source/${encodeURIComponent(item.sourceRecordId)}`}>Source</a>}
                <Pill>{item.score != null ? `${Math.round(item.score * 100)}%` : item.candidateType || "Candidate"}</Pill>
              </div>
            </div>
            <details className="review-workbench-item-details">
              <summary>Review details</summary>
              <div className="review-workbench-detail-grid">
                {item.sourcePath && <div><span>Source path</span><code>{item.sourcePath}</code></div>}
                {item.candidateId && <div><span>Candidate ID</span><code>{item.candidateId}</code></div>}
                {item.sessionId && <div><span>Session</span><code>{item.sessionId}</code></div>}
                {item.sourceRecordId && <div><span>Source record</span><code>{item.sourceRecordId}</code></div>}
              </div>
              {item.reviewGuidance && <p>{staffTriageSummary(item.reviewGuidance)}</p>}
              {reviewItemIsHighSimilarity(item) && (
                <div className="review-similarity-reasons">
                  <strong>Why this is high similarity</strong>
                  <div>
                    {reviewItemSimilarityReasons(item).map((reason) => <span key={reason}>{reason}</span>)}
                  </div>
                </div>
              )}
            </details>
            {(item.decisionOptions ?? []).length > 0 && (
              <div className="review-decision-options">
                <span>Available decisions</span>
                <div>
                  {(item.decisionOptions ?? []).map((option) => {
                    const action = reviewDecisionAction(item, option);
                    const state = actionStates[action.id];
                    const permissionCheck = action.permission ? permissionState.permissions[action.permission] : undefined;
                  return (
                    <button
                        type="button"
                        key={action.id}
                        disabled={!action.enabled || Boolean(state?.loading || state?.refreshing)}
                        title={`${option.permissionLabel || "Review"} · ${option.permission || "Review policy"}`}
                        onClick={() => runReviewDecision(item, option)}
                      >
                        {state?.loading ? "Running" : state?.refreshing ? "Refreshing" : option.label}
                        {option.permission && <PermissionGrantPill check={permissionCheck} hasActor={Boolean(actor)} loading={permissionState.loading} />}
                      </button>
                    );
                  })}
                </div>
                {(item.decisionOptions ?? []).map((option) => {
                  const action = reviewDecisionAction(item, option);
                  if (pendingDecisionConfirmationId !== action.id) return null;
                  const state = actionStates[action.id];
                  const permissionCheck = action.permission ? permissionState.permissions[action.permission] : undefined;
                  const permissionGate = processorPermissionGate(action, Boolean(actor), permissionCheck, permissionState.loading);
                  const guardedHint = processorActionGuardHint(action, Boolean(actor), permissionCheck, permissionState.loading);
                  const disabled = !action.enabled || !actor || permissionGate.blocked || Boolean(state?.loading || state?.refreshing);
                  return (
                    <ProcessorActionConfirmationPanel
                      key={`${action.id}:confirmation`}
                      action={action}
                      actor={actor}
                      disabled={disabled}
                      guardHint={guardedHint}
                      onCancel={() => setPendingDecisionConfirmationId(null)}
                      onConfirm={() => runReviewDecision(item, option, true)}
                      payload={action.payload ?? action.payloadTemplate ?? {}}
                    />
                  );
                })}
              </div>
            )}
            {(item.decisionOptions ?? []).map((option) => {
              const action = reviewDecisionAction(item, option);
              const state = actionStates[action.id];
              if (!state?.error && !state?.result && !state?.refreshedAt && !state?.refreshing) return null;
              return (
                <div className="review-decision-result" key={`${action.id}:result`}>
                  {state.refreshing && <small>Refreshing review queue after decision.</small>}
                  {state.refreshedAt && !state.refreshing && <small>Review queue refreshed at {formatTimestamp(state.refreshedAt)}.</small>}
                  {state.error && <p className="research-run-inspection error">{state.error}</p>}
                  {state.result && <ProcessorActionResult actor={actor} result={state.result} />}
                </div>
              );
            })}
          </article>
        )) : (
          <EmptyState icon={<ShieldCheck size={22} />} title={loading ? "Loading review queue" : "No review candidates visible"} body={queueMode === "all" ? reviewWorkbenchEmptyBody(workbench) : `${reviewQueueModeLabel(queueMode)} has no candidates in the current queue slice. Adjust filters or return to all visible candidates.`} />
        )}
      </div>

      {workbench?.raw && (
        <details className="raw-block">
          <summary>Review workbench diagnostics</summary>
          <pre>{JSON.stringify(workbench.raw, null, 2)}</pre>
        </details>
      )}
    </section>
  );
}

function GroupPills({
  items,
  label,
  onSelect
}: {
  items: Array<{ value: string; label: string; count: number }>;
  label: string;
  onSelect: (value: string) => void;
}) {
  if (items.length === 0) return null;
  return (
    <div className="review-workbench-group">
      <span>{label}</span>
      <div>
        {items.slice(0, 8).map((item) => (
          <button type="button" key={item.value} onClick={() => onSelect(item.value)}>
            {item.label} <strong>{item.count}</strong>
          </button>
        ))}
      </div>
    </div>
  );
}

function ProcessorReadinessPanel({
  actorId,
  onActorIdChange,
  onResearchRefresh,
  operationHistory,
  readiness,
  runs
}: {
  actorId: string;
  onActorIdChange: (value: string) => void;
  onResearchRefresh: () => Promise<void>;
  operationHistory?: ResearchResponse["processorOperationHistory"];
  readiness: NonNullable<ResearchResponse["processorReadiness"]>;
  runs: Record<string, unknown>[];
}) {
  const pending = readiness.review.pendingCount ?? 0;
  const approved = readiness.review.approvedCount ?? 0;
  const queueItems = readiness.reviewQueue?.items ?? [];
  const [runInspections, setRunInspections] = useState<Record<string, RunInspectionState>>({});
  const [actionStates, setActionStates] = useState<Record<string, ProcessorActionState>>({});
  const [permissionState, setPermissionState] = useState<ProcessorActorPermissionState>({ loading: false, permissions: {} });
  const [pendingConfirmationActionId, setPendingConfirmationActionId] = useState<string | null>(null);
  const [pendingDecisionConfirmationId, setPendingDecisionConfirmationId] = useState<string | null>(null);
  const [pendingRecoveryConfirmationId, setPendingRecoveryConfirmationId] = useState<string | null>(null);
  const [promotionModalOpen, setPromotionModalOpen] = useState(false);

  const trimmedActor = actorId.trim();
  const actor = trimmedActor ? { actorId: trimmedActor, authProvider: "navigator", subject: trimmedActor } satisfies NavigatorActor : undefined;
  const guardedActions = readiness.actions.filter((action) => action.requiresActor || action.mutates);
  const recoveryActionPermissions = useMemo(
    () => (operationHistory?.items ?? [])
      .flatMap((item) => item.recoveryActions ?? [])
      .map((action) => action.permission)
      .filter((permission): permission is string => Boolean(permission)),
    [operationHistory]
  );
  const permissionsToCheck = useMemo(
    () => {
      const actionPermissions = guardedActions.map((action) => action.permission);
      const decisionPermissions = (readiness.reviewQueue?.items ?? [])
        .flatMap((item) => item.decisionOptions ?? [])
        .map((option) => option.permission);
      return Array.from(new Set([...actionPermissions, ...decisionPermissions, ...recoveryActionPermissions].filter((permission): permission is string => Boolean(permission))));
    },
    [guardedActions, readiness.reviewQueue, recoveryActionPermissions]
  );
  const permissionKey = permissionsToCheck.join("|");

  useEffect(() => {
    let cancelled = false;
    if (!trimmedActor || permissionsToCheck.length === 0) {
      setPermissionState({ loading: false, permissions: {} });
      return () => {
        cancelled = true;
      };
    }
    setPermissionState((current) => ({ ...current, actorId: trimmedActor, error: null, loading: true }));
    fetchProcessorActorPermissions(trimmedActor, permissionsToCheck)
      .then((response) => {
        if (cancelled) return;
        const permissions = response.permissions.reduce<Record<string, ProcessorActorPermissionCheck>>((acc, item) => {
          acc[item.permission] = item;
          return acc;
        }, {});
        setPermissionState({ actorId: response.actorId, loading: false, permissions });
      })
      .catch((err: Error) => {
        if (!cancelled) setPermissionState({ actorId: trimmedActor, error: err.message, loading: false, permissions: {} });
      });
    return () => {
      cancelled = true;
    };
  }, [permissionKey, trimmedActor]);

  function processorActionPayload(action: ProcessorResearchAction): Record<string, unknown> {
    return action.payload ?? action.payloadTemplate ?? {};
  }

  function reviewDecisionAction(item: ProcessorReviewQueueItem, option: ProcessorReviewDecisionOption): ProcessorResearchAction {
    const payload = option.payloadTemplate ?? {};
    const candidateId = String(payload.candidate_id || item.candidateId || item.label);
    return {
      id: `review_queue:${candidateId}:${option.id}`,
      label: `${option.label} candidate`,
      module: option.module,
      jobType: option.jobType,
      mutates: option.mutates,
      permission: option.permission,
      permissionLabel: option.permissionLabel,
      requiresActor: option.requiresActor,
      roleHint: "Reviewer or operator with candidate review permission",
      confirmationRequired: option.confirmationRequired ?? true,
      confirmation: option.confirmation,
      enabled: option.enabled,
      status: option.status,
      payloadTemplate: payload
    };
  }

  function recoveryActionKey(runId: string, action: ProcessorOperationRecoveryAction): string {
    return `recovery:${runId}:${action.id}`;
  }

  function recoveryProcessorAction(runId: string, action: ProcessorOperationRecoveryAction): ProcessorResearchAction {
    return {
      id: recoveryActionKey(runId, action),
      label: action.label,
      module: "processor.runs",
      jobType: action.id,
      mutates: action.mutates,
      permission: action.permission,
      permissionLabel: action.permission ? "Run recovery permission" : "Run recovery policy",
      requiresActor: action.requiresActor,
      roleHint: "Operator with run recovery permission",
      confirmationRequired: action.mutates,
      confirmation: {
        title: `Confirm ${action.label}`,
        description: `${action.guidance || "This recovery action is actor-gated."} Endpoint details are available below.`,
        confirmLabel: `Confirm ${friendlyLabel(action.id)}`,
        checks: [
          "Navigator preflights the actor permission before forwarding.",
          "Review policy remains the authority for final authorization and audit.",
          "Research data refreshes after a successful recovery request.",
          `${action.method} ${action.endpoint}`
        ]
      },
      enabled: Boolean(action.navigatorExecutable),
      status: action.status,
      payloadTemplate: action.payloadTemplate ?? {},
      requestPreview: action.requestPreview,
    };
  }

  function runRecoveryAction(runId: string, action: ProcessorOperationRecoveryAction, confirmed = false) {
    const recoveryAction = recoveryProcessorAction(runId, action);
    if (!recoveryAction.enabled || actionStates[recoveryAction.id]?.loading) return;
    if (recoveryAction.mutates && recoveryAction.confirmationRequired && !confirmed) {
      setPendingRecoveryConfirmationId(recoveryAction.id);
      return;
    }
    if (recoveryAction.requiresActor && !actor) {
      setActionStates((current) => ({
        ...current,
        [recoveryAction.id]: { loading: false, error: "Actor ID required for this recovery action." }
      }));
      return;
    }
    const payload = processorActionPayload(recoveryAction);
    setPendingRecoveryConfirmationId((current) => current === recoveryAction.id ? null : current);
    setActionStates((current) => ({ ...current, [recoveryAction.id]: { loading: true } }));
    const operation = action.id === "retry_run"
      ? retryProcessorRun(runId, payload as { confirm_retry_run_id: string; idempotency_key?: string }, actor as NavigatorActor)
      : action.id === "cancel_run"
        ? cancelProcessorRun(runId, payload as { reason?: string }, actor as NavigatorActor)
        : action.id === "renew_lease"
          ? renewProcessorRunLease(runId, payload as { worker_id: string; lease_seconds?: number }, actor as NavigatorActor)
          : Promise.reject(new Error(`Unsupported recovery action: ${action.id}`));
    operation
      .then((result) => {
        setActionStates((current) => ({
          ...current,
          [recoveryAction.id]: { loading: false, refreshing: result.ok, result }
        }));
        if (result.ok) {
          return onResearchRefresh()
            .then(() => {
              setActionStates((current) => ({
                ...current,
                [recoveryAction.id]: {
                  ...current[recoveryAction.id],
                  loading: false,
                  refreshedAt: new Date().toISOString(),
                  refreshing: false
                }
              }));
            })
            .catch((err: Error) => {
              setActionStates((current) => ({
                ...current,
                [recoveryAction.id]: {
                  ...current[recoveryAction.id],
                  loading: false,
                  error: `Recovery request completed, but Research refresh failed: ${err.message}`,
                  refreshing: false
                }
              }));
            });
        }
        return undefined;
      })
      .catch((err: Error) => {
        setActionStates((current) => ({ ...current, [recoveryAction.id]: { loading: false, error: err.message } }));
      });
  }

  function runReviewDecision(item: ProcessorReviewQueueItem, option: ProcessorReviewDecisionOption, confirmed = false) {
    const action = reviewDecisionAction(item, option);
    if (!action.enabled || actionStates[action.id]?.loading) return;
    if (action.mutates && action.confirmationRequired && !confirmed) {
      setPendingDecisionConfirmationId(action.id);
      return;
    }
    if (action.requiresActor && !actor) {
      setActionStates((current) => ({
        ...current,
        [action.id]: { loading: false, error: "Actor ID required for this review decision." }
      }));
      return;
    }
    const payload = processorActionPayload(action);
    setPendingDecisionConfirmationId((current) => current === action.id ? null : current);
    setActionStates((current) => ({ ...current, [action.id]: { loading: true } }));
    const runner = action.executionMode === "background" ? runProcessorBackgroundJob : runProcessorJob;
    runner(action.module, { job_type: action.jobType, payload }, actor)
      .then((result) => {
        setActionStates((current) => ({
          ...current,
          [action.id]: { loading: false, refreshing: result.ok, result }
        }));
        if (result.ok) {
          return onResearchRefresh()
            .then(() => {
              setActionStates((current) => ({
                ...current,
                [action.id]: {
                  ...current[action.id],
                  loading: false,
                  refreshedAt: new Date().toISOString(),
                  refreshing: false
                }
              }));
            })
            .catch((err: Error) => {
              setActionStates((current) => ({
                ...current,
                [action.id]: {
                  ...current[action.id],
                  loading: false,
                  error: `Decision completed, but Research refresh failed: ${err.message}`,
                  refreshing: false
                }
              }));
            });
        }
        return undefined;
      })
      .catch((err: Error) => {
        setActionStates((current) => ({ ...current, [action.id]: { loading: false, error: err.message } }));
      });
  }

  function runResearchAction(action: ProcessorResearchAction, confirmed = false) {
    if (!action.enabled || actionStates[action.id]?.loading) return;
    if (action.mutates && action.confirmationRequired && !confirmed) {
      setPendingConfirmationActionId(action.id);
      return;
    }
    if (action.requiresActor && !actor) {
      setActionStates((current) => ({
        ...current,
        [action.id]: { loading: false, error: "Actor ID required for this Processor action." }
      }));
      return;
    }
    const payload = processorActionPayload(action);
    setPendingConfirmationActionId((current) => current === action.id ? null : current);
    setActionStates((current) => ({ ...current, [action.id]: { loading: true } }));
    const runner = action.executionMode === "background" ? runProcessorBackgroundJob : runProcessorJob;
    runner(action.module, { job_type: action.jobType, payload }, actor)
      .then((result) => {
        setActionStates((current) => ({
          ...current,
          [action.id]: { loading: false, refreshing: result.ok, result }
        }));
        if (result.ok) {
          return onResearchRefresh()
            .then(() => {
              setActionStates((current) => ({
                ...current,
                [action.id]: {
                  ...current[action.id],
                  loading: false,
                  refreshedAt: new Date().toISOString(),
                  refreshing: false
                }
              }));
            })
            .catch((err: Error) => {
              setActionStates((current) => ({
                ...current,
                [action.id]: {
                  ...current[action.id],
                  loading: false,
                  error: `Action completed, but Research refresh failed: ${err.message}`,
                  refreshing: false
                }
              }));
            });
        }
        return undefined;
      })
      .catch((err: Error) => {
        setActionStates((current) => ({ ...current, [action.id]: { loading: false, error: err.message } }));
      });
  }

  function inspectRun(runId: string) {
    if (!runId || runInspections[runId]?.loading) return;
    setRunInspections((current) => ({ ...current, [runId]: { loading: true } }));
    fetchProcessorRunInspection(runId)
      .then((data) => {
        setRunInspections((current) => ({ ...current, [runId]: { loading: false, data } }));
      })
      .catch((err: Error) => {
        setRunInspections((current) => ({ ...current, [runId]: { loading: false, error: err.message } }));
      });
  }

  return (
    <section className="panel-block research-processor-panel">
      <div className="processor-readiness-head">
        <div>
          <h3>Review service readiness</h3>
          <p>{readiness.sourceStatus.nextAction ? `Next suggested action: ${staffTriageLabel(readiness.sourceStatus.nextAction)}` : "Readiness is shown from read-only service jobs."}</p>
        </div>
        <Pill tone={readiness.promotion.canExecute ? "strong" : undefined}>{friendlyLabel(readiness.promotion.status || readiness.sourceStatus.status)}</Pill>
      </div>
      <div className="processor-readiness-grid">
        <ReadinessCard title="Source" status={readiness.sourceStatus.status} details={[
          `Intake: ${staffTriageLabel(readiness.sourceStatus.ingestorStatus || "unknown")}`,
          `Candidate extraction: ${staffTriageLabel(readiness.sourceStatus.normalizerStatus || "unknown")}`
        ]} />
        <ReadinessCard title="Review" status={readiness.review.status} details={[
          `${pending} pending`,
          `${approved} approved`,
          `${readiness.review.rejectedCount ?? 0} rejected`
        ]} />
        <ReadinessCard title="Promotion" status={readiness.promotion.status} details={[
          readiness.promotion.canExecute ? "Can execute promotion" : "Promotion not executable",
          `${readiness.promotion.operationCount ?? 0} planned operations`
        ]} />
      </div>
      {operationHistory && (
        <ProcessorOperationHistoryPanel
          actor={actor}
          history={operationHistory}
          onCancelRecovery={() => setPendingRecoveryConfirmationId(null)}
          onRunRecoveryAction={runRecoveryAction}
          pendingRecoveryConfirmationId={pendingRecoveryConfirmationId}
          permissionLoading={permissionState.loading}
          permissionState={permissionState}
          recoveryProcessorAction={recoveryProcessorAction}
          recoveryStates={actionStates}
        />
      )}
      {(guardedActions.length > 0 || recoveryActionPermissions.length > 0) && (
        <div className="processor-actor-gate">
          <div>
            <strong>Guarded review actions</strong>
            <span>
              {actor ? `Actor: ${actor.actorId}` : "Actor required before review, promotion, or recovery jobs can run."}
            </span>
            {permissionState.loading && <span>Checking permission grants.</span>}
            {permissionState.error && <span>Permission check unavailable: {permissionState.error}</span>}
          </div>
          <label>
            <span>Research actor ID</span>
            <input
              value={actorId}
              onChange={(event) => onActorIdChange(event.target.value)}
              placeholder="navigator:researcher:..."
            />
          </label>
        </div>
      )}
      {actor && permissionsToCheck.length > 0 && (
        <ActorPermissionDetails
          actorId={actor.actorId}
          loading={permissionState.loading}
          permissions={permissionsToCheck.map((permission) => permissionState.permissions[permission]).filter(Boolean)}
        />
      )}
      {readiness.reviewWorkflowPlan && <ProcessorReviewWorkflowPlanPanel plan={readiness.reviewWorkflowPlan} />}
      {readiness.promotion.completionPlan && (
        <ProcessorPromotionCompletionPanel
          onOpen={() => setPromotionModalOpen(true)}
          plan={readiness.promotion.completionPlan}
        />
      )}
      <div className="research-action-list">
        {readiness.actions.map((action) => {
          const actionState = actionStates[action.id];
          const needsActor = action.requiresActor && !actor;
          const permissionCheck = action.permission ? permissionState.permissions[action.permission] : undefined;
          const permissionGate = processorPermissionGate(action, Boolean(actor), permissionCheck, permissionState.loading);
          const guardedHint = processorActionGuardHint(action, Boolean(actor), permissionCheck, permissionState.loading);
          const confirmingAction = pendingConfirmationActionId === action.id;
          const disabled = !action.enabled || needsActor || permissionGate.blocked || Boolean(actionState?.loading || actionState?.refreshing);
          const actionButtonDisabled = action.mutates && action.confirmationRequired
            ? !action.enabled || confirmingAction || Boolean(actionState?.loading || actionState?.refreshing)
            : disabled || confirmingAction;
          return (
            <article key={action.id} className={action.enabled ? "enabled" : "disabled"}>
              <div>
                <strong>{action.label}</strong>
                <span>{action.module}.{action.jobType} · {action.executionMode === "background" ? "background" : "foreground"} · {action.mutates ? "mutating" : "read-only"}{action.requiresActor ? " · actor required" : ""}</span>
                {(action.permission || action.permissionLabel || action.roleHint) && (
                  <div className="research-action-policy">
                    {action.permissionLabel && <span>{action.permissionLabel}</span>}
                    {action.confirmationRequired && <span>Confirmation required</span>}
                    {action.permission && <code>{action.permission}</code>}
                    {action.permission && (
                      <PermissionGrantPill
                        check={permissionState.permissions[action.permission]}
                        hasActor={Boolean(actor)}
                        loading={permissionState.loading}
                      />
                    )}
                    {action.roleHint && <em>{action.roleHint}</em>}
                  </div>
                )}
              </div>
              <div className="research-action-controls">
                <Pill>{action.enabled ? friendlyLabel(action.status || "available") : "Unavailable"}</Pill>
                <button type="button" disabled={actionButtonDisabled} onClick={() => runResearchAction(action)}>
                  {actionState?.loading
                    ? "Running"
                    : actionState?.refreshing
                      ? "Refreshing"
                      : action.mutates && action.confirmationRequired
                        ? confirmingAction ? "Reviewing" : "Review guarded"
                        : action.mutates ? "Run guarded" : "Run"}
                </button>
              </div>
              {guardedHint && <small>{guardedHint}</small>}
              {confirmingAction && (
                <ProcessorActionConfirmationPanel
                  action={action}
                  actor={actor}
                  disabled={disabled}
                  guardHint={guardedHint}
                  onCancel={() => setPendingConfirmationActionId(null)}
                  onConfirm={() => runResearchAction(action, true)}
                  payload={processorActionPayload(action)}
                />
              )}
              {actionState?.refreshing && <small>Refreshing Research data after Processor completion.</small>}
              {actionState?.refreshedAt && !actionState.refreshing && (
                <small>Research data refreshed at {formatTimestamp(actionState.refreshedAt)}.</small>
              )}
              {actionState?.error && <p className="research-run-inspection error">{actionState.error}</p>}
              {actionState?.result && <ProcessorActionResult actor={actor} result={actionState.result} />}
            </article>
          );
        })}
      </div>
      {readiness.promotion.messages && readiness.promotion.messages.length > 0 && (
        <p className="muted">{readiness.promotion.messages.slice(0, 3).map(friendlyLabel).join(" · ")}</p>
      )}
      {queueItems.length > 0 && (
        <div className="research-queue-list">
          <h4>Review queue sample</h4>
          {queueItems.slice(0, 5).map((item) => (
            <article key={item.candidateId || `${item.sessionId}:${item.label}`}>
              <div>
                <strong>{item.label}</strong>
                <span>{friendlyLabel(item.candidateKind || "candidate")} · {friendlyLabel(item.reviewStatus || "unknown")}{item.matchStatus ? ` · ${friendlyLabel(item.matchStatus)}` : ""}</span>
                {item.sourcePath && <span>Source path: {item.sourcePath}</span>}
              </div>
              <small>{item.score != null ? `${Math.round(item.score * 100)}%` : ""}</small>
              {(item.decisionOptions ?? []).length > 0 && (
                <div className="review-decision-options">
                  <span>{staffTriageSummary(item.reviewGuidance) || "Review decisions"}</span>
                  <div>
                    {(item.decisionOptions ?? []).slice(0, 4).map((option) => {
                      const decisionAction = reviewDecisionAction(item, option);
                      const decisionState = actionStates[decisionAction.id];
                      const confirmingDecision = pendingDecisionConfirmationId === decisionAction.id;
                      const previewDisabled = !decisionAction.enabled || confirmingDecision || Boolean(decisionState?.loading || decisionState?.refreshing);
                      return (
                        <button
                          type="button"
                          key={decisionAction.id}
                          disabled={previewDisabled}
                          title={`${option.permissionLabel || "Review"} · ${option.permission || "Review policy"}`}
                          onClick={() => runReviewDecision(item, option)}
                        >
                          {decisionState?.loading ? "Running" : decisionState?.refreshing ? "Refreshing" : option.label}
                        </button>
                      );
                    })}
                  </div>
                  {(item.decisionOptions ?? []).slice(0, 4).map((option) => {
                    const decisionAction = reviewDecisionAction(item, option);
                    if (pendingDecisionConfirmationId !== decisionAction.id) return null;
                    const decisionState = actionStates[decisionAction.id];
                    const permissionCheck = decisionAction.permission ? permissionState.permissions[decisionAction.permission] : undefined;
                    const permissionGate = processorPermissionGate(decisionAction, Boolean(actor), permissionCheck, permissionState.loading);
                    const guardedHint = processorActionGuardHint(decisionAction, Boolean(actor), permissionCheck, permissionState.loading);
                    const confirmDisabled = !decisionAction.enabled || !actor || permissionGate.blocked || Boolean(decisionState?.loading || decisionState?.refreshing);
                    return (
                      <ProcessorActionConfirmationPanel
                        key={`${decisionAction.id}:confirmation`}
                        action={decisionAction}
                        actor={actor}
                        disabled={confirmDisabled}
                        guardHint={guardedHint}
                        onCancel={() => setPendingDecisionConfirmationId(null)}
                        onConfirm={() => runReviewDecision(item, option, true)}
                        payload={processorActionPayload(decisionAction)}
                      />
                    );
                  })}
                </div>
              )}
              {item.decisionOptions?.map((option) => {
                const decisionAction = reviewDecisionAction(item, option);
                const decisionState = actionStates[decisionAction.id];
                if (!decisionState?.error && !decisionState?.result && !decisionState?.refreshedAt && !decisionState?.refreshing) return null;
                return (
                  <div className="review-decision-result" key={`${decisionAction.id}:result`}>
                    {decisionState.refreshing && <small>Refreshing research data after review decision.</small>}
                    {decisionState.refreshedAt && !decisionState.refreshing && <small>Research data refreshed at {formatTimestamp(decisionState.refreshedAt)}.</small>}
                    {decisionState.error && <p className="research-run-inspection error">{decisionState.error}</p>}
                    {decisionState.result && <ProcessorActionResult actor={actor} result={decisionState.result} />}
                  </div>
                );
              })}
            </article>
          ))}
        </div>
      )}
      <details className="operation-history-details">
        <summary>Recent service runs</summary>
        <div className="research-run-list">
          {runs.length > 0 ? runs.slice(0, 5).map((run) => {
            const runId = String(run.run_id || "");
            const runInspectionState = runId ? runInspections[runId] : undefined;
            const inspection = typeof run.inspection === "object" && run.inspection !== null ? run.inspection as Record<string, unknown> : {};
            const inspectionUrl = String(run.inspectionUrl || inspection.inspectionUrl || "");
            const eventsUrl = String(run.eventsUrl || inspection.eventsUrl || "");
            const scope = typeof run.scope === "object" && run.scope !== null ? run.scope as Record<string, unknown> : {};
            const scopeLabel = scope.label ? String(scope.label) : "";
            return (
              <article className="research-run-card" key={String(run.run_id || `${run.module_name}:${run.job_type}:${run.started_at}`)}>
                <div>
                  <strong>{staffTriageLabel(String(run.job_type || "job"))}</strong>
                  <span>{String(run.status || "unknown")} · {String(run.lifecycle_state || "state unknown")}</span>
                  {Boolean(run.module_name) && <small>{String(run.module_name)}</small>}
                  {scopeLabel && <span>{scopeLabel}</span>}
                  {(inspectionUrl || eventsUrl) && (
                    <div className="research-run-actions">
                      {inspectionUrl && (
                        <button type="button" onClick={() => inspectRun(runId)} disabled={!runId || runInspectionState?.loading}>
                          {runInspectionState?.loading ? "Loading" : "Inspect"}
                        </button>
                      )}
                      {inspectionUrl && <a href={inspectionUrl} target="_blank" rel="noreferrer">API</a>}
                      {eventsUrl && <a href={eventsUrl} target="_blank" rel="noreferrer">Events</a>}
                    </div>
                  )}
                </div>
                <small>{String(run.started_at || run.finished_at || "")}</small>
                {runInspectionState?.error && <p className="research-run-inspection error">{runInspectionState.error}</p>}
                {runInspectionState?.data && <RunInspectionDetails inspection={runInspectionState.data} />}
              </article>
            );
          }) : <p className="muted">No scoped service runs are recorded for this source record or session yet.</p>}
        </div>
      </details>
      {promotionModalOpen && readiness.promotion.completionPlan && (
        <ProcessorPromotionCompletionModal
          onClose={() => setPromotionModalOpen(false)}
          plan={readiness.promotion.completionPlan}
        />
      )}
    </section>
  );
}

function ProcessorActionConfirmationPanel({
  action,
  actor,
  disabled,
  guardHint,
  onCancel,
  onConfirm,
  payload
}: {
  action: ProcessorResearchAction;
  actor?: NavigatorActor;
  disabled: boolean;
  guardHint?: string | null;
  onCancel: () => void;
  onConfirm: () => void;
  payload: Record<string, unknown>;
}) {
  const confirmation = action.confirmation ?? {};
  const checks = confirmation.checks ?? [];
  const requestPreview = buildProcessorRequestPreview(action, actor, payload);
  const requestPreviewJson = requestPreview ? JSON.stringify(requestPreview, null, 2) : "";
  const payloadJson = JSON.stringify(payload, null, 2);
  const idempotencyHeader = requestPreview?.headers?.["Idempotency-Key"];
  const title = staffTriageSummary(confirmation.title) || `Confirm ${staffTriageLabel(action.label)}`;
  const description = staffTriageSummary(confirmation.description)
    || "This guarded review action requires an explicit actor and confirmation before Navigator forwards it.";
  const policyLabel = action.permissionLabel ? staffTriageSummary(action.permissionLabel) : "Guarded action";
  return (
    <div className="processor-action-confirmation">
      <div className="processor-confirmation-head">
        <div>
          <strong>{title}</strong>
          <p>{description}</p>
        </div>
        <Pill>{policyLabel}</Pill>
      </div>
      <div className="processor-confirmation-grid">
        <span>Actor: {actor?.actorId || "Actor required"}</span>
        <span>Action: {staffTriageLabel(action.jobType || action.label)}</span>
        <span>Mode: {action.executionMode === "background" ? "Background run" : "Foreground job"}</span>
        <span>{action.permission ? "Policy grant required" : "Review policy"}</span>
        <span>{action.mutates ? "Mutating" : "Read-only"}</span>
      </div>
      {checks.length > 0 && (
        <div className="processor-confirmation-checks">
          {checks.slice(0, 5).map((check) => <span key={check}>{staffTriageSummary(check)}</span>)}
        </div>
      )}
      {guardHint && <p className="processor-confirmation-guard">{guardHint}</p>}
      {requestPreview && (
        <details className="processor-confirmation-request">
          <summary>Navigator request preview</summary>
          <div className="processor-confirmation-copy-actions">
            {requestPreview.navigatorEndpoint && <CopyButton label="Copy endpoint" value={requestPreview.navigatorEndpoint} />}
            {idempotencyHeader && <CopyButton label="Copy idempotency key" value={idempotencyHeader} />}
            <CopyButton label="Copy payload" value={payloadJson} />
            <CopyButton label="Copy request preview" value={requestPreviewJson} />
          </div>
          <pre>{requestPreviewJson}</pre>
        </details>
      )}
      <details className="processor-confirmation-payload">
        <summary>Technical payload</summary>
        <pre>{JSON.stringify({ job_type: action.jobType, payload }, null, 2)}</pre>
      </details>
      <div className="processor-confirmation-actions">
        <button type="button" className="secondary" onClick={onCancel}>Cancel</button>
        <button type="button" onClick={onConfirm} disabled={disabled}>
          {staffTriageSummary(confirmation.confirmLabel) || "Confirm action"}
        </button>
      </div>
    </div>
  );
}

function buildProcessorRequestPreview(
  action: ProcessorResearchAction,
  actor: NavigatorActor | undefined,
  payload: Record<string, unknown>
): ProcessorRequestPreview | null {
  if (!action.requestPreview) return null;
  const actorHeader = actor?.actorId || action.requestPreview.headers?.["X-Navigator-Actor-Id"] || "<required actor id>";
  const headers: Record<string, string | null | undefined> = {
    ...(action.requestPreview.headers ?? {}),
    "X-Navigator-Actor-Id": actorHeader
  };
  return {
    method: action.requestPreview.method || "POST",
    navigatorEndpoint: action.requestPreview.navigatorEndpoint || null,
    headers,
    body: action.requestPreview.body ?? payload
  };
}

function ProcessorOperationHistoryPanel({
  actor,
  history,
  onCancelRecovery,
  onRunRecoveryAction,
  pendingRecoveryConfirmationId,
  permissionLoading,
  permissionState,
  recoveryProcessorAction,
  recoveryStates
}: {
  actor?: NavigatorActor;
  history: NonNullable<ResearchResponse["processorOperationHistory"]>;
  onCancelRecovery: () => void;
  onRunRecoveryAction: (runId: string, action: ProcessorOperationRecoveryAction, confirmed?: boolean) => void;
  pendingRecoveryConfirmationId: string | null;
  permissionLoading: boolean;
  permissionState: ProcessorActorPermissionState;
  recoveryProcessorAction: (runId: string, action: ProcessorOperationRecoveryAction) => ProcessorResearchAction;
  recoveryStates: Record<string, ProcessorActionState>;
}) {
  const items = history.items ?? [];
  const historyLabel = staffTriageSummary(history.label);
  return (
    <div className="processor-operation-history">
      <div className="processor-operation-head">
        <div>
          <h4>Review operation history</h4>
          {historyLabel && historyLabel !== "Review operation history" && <p>{historyLabel}</p>}
        </div>
        <Pill>{friendlyLabel(history.status || "unknown")}</Pill>
      </div>
      <div className="processor-operation-metrics">
        <span>{history.runCount ?? 0} scoped run{history.runCount === 1 ? "" : "s"}</span>
        <span>{history.completedCount ?? 0} completed</span>
        <span>{history.activeCount ?? 0} active</span>
        <span>{history.failedCount ?? 0} failed</span>
        <span>{history.recoveryActionCount ?? 0} recovery actions</span>
        <span>{history.authorizationEventCount ?? 0} authorization events</span>
      </div>
      <ProcessorAuthorizationAuditPanel summary={history.authorizationSummary} />
      {items.length > 0 ? (
        <details className="operation-history-details">
          <summary>Operation records</summary>
          <div className="research-run-list processor-operation-items">
          {items.slice(0, 4).map((item) => {
            const runId = item.runId || `${item.module}:${item.jobType}:${item.startedAt}`;
            return (
              <article key={runId || item.jobType || "operation"} className="research-run-card">
                <div>
                  <strong>{staffTriageLabel(item.jobType || "job")}</strong>
                  <span>{friendlyLabel(item.status || "unknown")} · {friendlyLabel(item.lifecycleState || item.rawStatus || "state unknown")}</span>
                  {item.module && <small>{item.module}</small>}
                  {item.scopeLabel && <span>{item.scopeLabel}</span>}
                  {item.errorMessage && <span>{item.errorMessage}</span>}
                  {(item.authorizationEvents ?? []).length > 0 && (
                    <div className="processor-operation-auth-events">
                      <strong>{item.authorizationEventCount ?? item.authorizationEvents?.length ?? 0} matching authorization event{(item.authorizationEventCount ?? 0) === 1 ? "" : "s"}</strong>
                      {(item.authorizationEvents ?? []).slice(0, 2).map((event) => (
                        <span key={String(event.id || `${event.permission}:${event.createdAt}`)}>
                          {friendlyLabel(event.decision || "unknown")} · {event.permission || "Review policy"} · {event.actorId || "unknown actor"}
                        </span>
                      ))}
                    </div>
                  )}
                </div>
                <small>{item.startedAt || item.finishedAt || ""}</small>
                {(item.recoveryActions ?? []).length > 0 && (
                  <div className="processor-recovery-actions">
                    <strong>Recovery actions</strong>
                    {(item.recoveryActions ?? []).slice(0, 3).map((action) => {
                      const recoveryAction = recoveryProcessorAction(runId, action);
                      const state = recoveryStates[recoveryAction.id];
                      const permissionCheck = recoveryAction.permission ? permissionState.permissions[recoveryAction.permission] : undefined;
                      const permissionGate = processorPermissionGate(recoveryAction, Boolean(actor), permissionCheck, permissionLoading);
                      const guardedHint = processorActionGuardHint(recoveryAction, Boolean(actor), permissionCheck, permissionLoading);
                      const confirming = pendingRecoveryConfirmationId === recoveryAction.id;
                      const disabled = !recoveryAction.enabled || !actor || permissionGate.blocked || Boolean(state?.loading || state?.refreshing);
                      const previewDisabled = !recoveryAction.enabled || confirming || Boolean(state?.loading || state?.refreshing);
                      return (
                        <div key={action.id} className="processor-recovery-action">
                          <div>
                            <span>{action.label}</span>
                            <code>{action.method} {action.endpoint}</code>
                            {action.permission && <code>{action.permission}</code>}
                            {action.guidance && <em>{action.guidance}</em>}
                            {action.permission && (
                              <PermissionGrantPill
                                check={permissionCheck}
                                hasActor={Boolean(actor)}
                                loading={permissionLoading}
                              />
                            )}
                          </div>
                          <div className="processor-recovery-controls">
                            <Pill>{action.navigatorExecutable ? "Guarded preview" : "Read-only plan"}</Pill>
                            <button type="button" disabled={previewDisabled} onClick={() => onRunRecoveryAction(runId, action)}>
                              {state?.loading ? "Running" : state?.refreshing ? "Refreshing" : confirming ? "Reviewing" : "Review recovery"}
                            </button>
                          </div>
                          {action.payloadTemplate && <pre>{JSON.stringify(action.payloadTemplate, null, 2)}</pre>}
                          {guardedHint && <small>{guardedHint}</small>}
                          {confirming && (
                            <ProcessorActionConfirmationPanel
                              action={recoveryAction}
                              actor={actor}
                              disabled={disabled}
                              guardHint={guardedHint}
                              onCancel={onCancelRecovery}
                              onConfirm={() => onRunRecoveryAction(runId, action, true)}
                              payload={recoveryAction.payloadTemplate ?? {}}
                            />
                          )}
                          {state?.refreshing && <small>Refreshing research data after recovery request.</small>}
                          {state?.refreshedAt && !state.refreshing && (
                            <small>Research data refreshed at {formatTimestamp(state.refreshedAt)}.</small>
                          )}
                          {state?.error && <p className="research-run-inspection error">{state.error}</p>}
                          {state?.result && <ProcessorActionResult actor={actor} result={state.result} />}
                        </div>
                      );
                    })}
                  </div>
                )}
              </article>
            );
          })}
          </div>
        </details>
      ) : (
        <p className="muted">No scoped review-service runs are recorded for this entity yet.</p>
      )}
      {(history.recoveryActionCount ?? 0) === 0 && (
        <p className="muted">Recovery actions appear here for failed or active service runs as read-only plans before execution controls are enabled.</p>
      )}
    </div>
  );
}

function ProcessorAuthorizationAuditPanel({ summary }: { summary?: NonNullable<ResearchResponse["processorOperationHistory"]>["authorizationSummary"] }) {
  if (!summary) return null;
  const recent = summary.recent ?? [];
  return (
    <div className="processor-authorization-audit">
      <div className="section-heading">
        <h4>Authorization audit context</h4>
        <span>{friendlyLabel(summary.status || "unknown")}</span>
      </div>
      <div className="processor-authorization-metrics">
        <span>{summary.totalCount ?? 0} scoped events</span>
        <span>{summary.allowedCount ?? 0} allowed</span>
        <span>{summary.deniedCount ?? 0} denied</span>
        <span>{summary.latestCreatedAt ? `Latest ${formatTimestamp(summary.latestCreatedAt)}` : "No authorization event yet"}</span>
      </div>
      <p>{staffTriageSummary(summary.ownership) || "Review services own authorization decisions, policy enforcement, and audit persistence; Navigator displays this scoped read-only summary."}</p>
      {recent.length > 0 ? (
        <div className="processor-authorization-events">
          {recent.slice(0, 4).map((event) => (
            <article key={String(event.id || `${event.permission}:${event.createdAt}`)}>
              <div>
                <strong>{friendlyLabel(event.decision || "unknown")}</strong>
                <span>{event.permission || "Review policy"}</span>
                <span>{staffTriageLabel(event.jobType || "job")}</span>
                <span>{event.actorId || "unknown actor"}</span>
              </div>
              <small>{event.createdAt ? formatTimestamp(event.createdAt) : ""}</small>
            </article>
          ))}
        </div>
      ) : (
        <p className="muted">Authorization audit context appears here after scoped permission decisions are recorded for this source record or candidate session.</p>
      )}
    </div>
  );
}

function RunInspectionDetails({ inspection }: { inspection: ProcessorRunInspection }) {
  return (
    <div className="research-run-inspection">
      <InspectionResult title="Run detail" result={inspection.run} />
      <InspectionResult title="Logs" result={inspection.logs} />
      <InspectionResult title="Events" result={inspection.events} />
    </div>
  );
}

