function ActorPermissionDetails({
  actorId,
  loading,
  permissions
}: {
  actorId: string;
  loading: boolean;
  permissions: ProcessorActorPermissionCheck[];
}) {
  const latestEvents = permissions
    .flatMap((permission) => permission.recentAuthorizationEvents ?? [])
    .slice(0, 5);
  return (
    <details className="processor-actor-details">
      <summary>
        <span>Actor policy context</span>
        <Pill>{loading ? "Checking" : `${permissions.filter((permission) => permission.allowed).length}/${permissions.length} grants`}</Pill>
      </summary>
      <div className="processor-actor-details-grid">
        <div>
          <strong>{actorId}</strong>
          <span>{loading ? "Grant check in progress" : "Read-only Navigator preflight"}</span>
        </div>
        {permissions.map((permission) => (
          <div key={permission.permission}>
            <strong>{permission.permission}</strong>
            <span>
              {permission.ok ? (permission.allowed ? "Grant found" : "Grant not found") : "Grant check unavailable"}
              {typeof permission.activeGrantCount === "number" ? ` · ${permission.activeGrantCount} active` : ""}
              {typeof permission.grantCount === "number" ? ` / ${permission.grantCount} total` : ""}
            </span>
            {(permission.aliases ?? []).length > 0 && (
              <span>Alias grants: {(permission.aliases ?? []).join(", ")}</span>
            )}
            {(permission.matchedPermissions ?? []).length > 1 && (
              <span>Matched: {(permission.matchedPermissions ?? []).join(", ")}</span>
            )}
          </div>
        ))}
      </div>
      {latestEvents.length > 0 && (
        <div className="processor-actor-events">
          <strong>Recent authorization decisions</strong>
          {latestEvents.map((event, index) => (
            <span key={String(event.authorization_event_id || `${event.permission}:${event.created_at}:${index}`)}>
              {formatAuthEvent(event)}
            </span>
          ))}
        </div>
      )}
    </details>
  );
}

function PermissionGrantPill({
  check,
  hasActor,
  loading
}: {
  check?: ProcessorActorPermissionCheck;
  hasActor: boolean;
  loading: boolean;
}) {
  if (!hasActor) return <em>Grant unchecked</em>;
  if (loading) return <em>Checking grant</em>;
  if (!check) return <em>Grant unknown</em>;
  if (!check.ok) return <em>Grant check unavailable</em>;
  const details: string[] = [];
  if (typeof check.activeGrantCount === "number") {
    details.push(`${check.activeGrantCount} active`);
  }
  const decision = latestAuthorizationDecision(check.latestAuthorizationEvent);
  if (decision) details.push(`last ${friendlyLabel(decision)}`);
  return <em>{[check.allowed ? "Grant found" : "Grant not found", ...details].join(" · ")}</em>;
}

function latestAuthorizationDecision(event?: Record<string, unknown> | null): string | null {
  const decision = event?.decision;
  return typeof decision === "string" && decision.trim() ? decision.trim() : null;
}

function formatAuthEvent(event: Record<string, unknown>): string {
  const permission = typeof event.permission === "string" ? event.permission : "permission";
  const decision = typeof event.decision === "string" ? friendlyLabel(event.decision) : "Decision";
  const job = typeof event.job_type === "string" ? ` · ${friendlyLabel(event.job_type)}` : "";
  const created = typeof event.created_at === "string" ? ` · ${formatTimestamp(event.created_at)}` : "";
  return `${permission}: ${decision}${job}${created}`;
}

function ProcessorActionResult({ actor, result }: { actor?: NavigatorActor; result: SafeResult }) {
  const payload = result.ok ? result.data ?? result.processor ?? null : result.error || "Review action failed";
  const runId = findProcessorRunId(payload);
  const status = findProcessorRunStatus(payload);
  return (
    <details className={`processor-action-result ${result.ok ? "ok" : "error"}`}>
      <summary>{result.ok ? "Review service result" : "Review service error"}</summary>
      {runId && (
        <div className="processor-action-followup">
          <span>
            Review service run {status ? `is ${friendlyLabel(status)}` : "created"}.
          </span>
          <a href={processorRunInspectionUrl(runId, actor)} target="_blank" rel="noreferrer">
            Inspect run
          </a>
        </div>
      )}
      <pre>{JSON.stringify(payload, null, 2)}</pre>
    </details>
  );
}

function findProcessorRunId(value: unknown): string | null {
  return (
    findStringField(value, ["run_id", "runId", "processor_run_id", "processorRunId"], ["run", "processorRun", "backgroundRun", "job", "data"]) ||
    findStringField(value, ["id"], ["run", "processorRun", "backgroundRun", "job"])
  );
}

function findProcessorRunStatus(value: unknown): string | null {
  return findStringField(value, ["status", "lifecycle_state", "lifecycleState", "state"], ["run", "processorRun", "backgroundRun", "job", "data"]);
}

function findStringField(value: unknown, fieldNames: string[], containers: string[], depth = 0): string | null {
  if (!value || typeof value !== "object" || depth > 4) return null;
  const record = value as Record<string, unknown>;
  for (const fieldName of fieldNames) {
    const candidate = record[fieldName];
    if (typeof candidate === "string" && candidate.trim()) return candidate.trim();
  }
  for (const container of containers) {
    const nested = record[container];
    const found = findStringField(nested, fieldNames, containers, depth + 1);
    if (found) return found;
  }
  return null;
}

function InspectionResult({ result, title }: { result: SafeResult; title: string }) {
  const payload = result.ok ? result.data ?? result.processor ?? null : result.error || "Unavailable";
  return (
    <details>
      <summary>
        <span>{title}</span>
        <Pill>{result.ok ? "Available" : "Unavailable"}</Pill>
      </summary>
      <pre>{formatInspectionPayload(payload)}</pre>
    </details>
  );
}

