function ContributionComposer({
  actorId,
  organ,
  onActorIdChange,
  onSubmitted
}: {
  actorId: string;
  organ: OrganDetail;
  onActorIdChange: (value: string) => void;
  onSubmitted: (contribution: Contribution) => void;
}) {
  const [draftTarget, setDraftTarget] = useState<ContributionDraftTarget | null>(() => readContributionDraft());
  const [type, setType] = useState(draftTarget?.contributionType || "add_fact");
  const [field, setField] = useState(draftTarget?.field || "builder");
  const [value, setValue] = useState(draftTarget?.value || "");
  const [comment, setComment] = useState(draftTarget?.comment || "");
  const [evidenceUrl, setEvidenceUrl] = useState(draftTarget?.evidenceUrl || "");
  const [status, setStatus] = useState<string | null>(null);
  const attachmentPreview = contributionAttachmentPreview(type, evidenceUrl);
  const factFields = organ.facts.map((fact) => fact.key);
  const draftFieldMissing = Boolean(field && !factFields.includes(field));
  void onActorIdChange;

  useEffect(() => {
    const applyDraft = (draft: ContributionDraftTarget | null) => {
      setDraftTarget(draft);
      if (!draft) return;
      setType(draft.contributionType);
      if (draft.field) setField(draft.field);
      setValue(draft.value || "");
      setComment(draft.comment || "");
      setEvidenceUrl(draft.evidenceUrl || "");
      setStatus(`This suggestion is linked to ${draft.label}.`);
    };
    applyDraft(readContributionDraft());
    const onDraft = (event: Event) => {
      const detail = (event as CustomEvent<ContributionDraftTarget>).detail;
      applyDraft(detail);
    };
    window.addEventListener("modavis:navigator:contribution-target", onDraft);
    return () => window.removeEventListener("modavis:navigator:contribution-target", onDraft);
  }, []);

  async function submit(event: FormEvent) {
    event.preventDefault();
    setStatus(null);
    if (!actorId.trim()) {
      setStatus("Please log in before submitting this suggestion.");
      return;
    }
    const request: ContributionRequest = {
      target_type: draftTarget?.targetType || "entity",
      target_id: draftTarget?.targetId || organ.id,
      contribution_type: type,
      claim: {
        ...(value ? { field, value } : {}),
        ...(draftTarget ? {
          target_entity_id: organ.id,
          target_entity_mdvs_id: organ.mdvsId,
          evidence_target: draftTarget.evidenceTarget,
        } : {}),
      },
      comment,
      evidence_url: evidenceUrl,
      evidence_title: evidenceUrl ? (draftTarget?.evidenceTitle || `${organ.title} supporting evidence`) : draftTarget?.evidenceTitle,
      license: "unspecified"
    };
    const result: SafeResult<{ contribution: Contribution }> & { contribution?: Contribution } = await submitContribution(request);
    const contribution = result.data?.contribution ?? result.contribution;
    if (!result.ok || !contribution) {
      setStatus(result.error || "The suggestion could not be submitted.");
      return;
    }
    onSubmitted(contribution);
    setValue("");
    setComment("");
    setEvidenceUrl("");
    setDraftTarget(null);
    try {
      window.localStorage.removeItem(CONTRIBUTION_TARGET_STORAGE_KEY);
    } catch {
      undefined;
    }
    setStatus("Suggestion submitted for review.");
  }

  return (
    <form className="contribution-form" onSubmit={submit}>
      <div className="contribution-form-head">
        <h3>Suggest an improvement</h3>
        <p>Share a correction, source link, photo, document, or note for this organ. Suggestions are reviewed before they change the public page.</p>
      </div>
      {draftTarget && (
        <div className="contribution-target-preview">
          <div>
            <strong>{draftTarget.label}</strong>
            <span>{friendlyLabel(draftTarget.targetType)} on this organ page</span>
          </div>
          <button
            type="button"
            className="text-link-button"
            onClick={() => {
              setDraftTarget(null);
              try {
                window.localStorage.removeItem(CONTRIBUTION_TARGET_STORAGE_KEY);
              } catch {
                undefined;
              }
              setStatus("Linked target cleared.");
            }}
          >
            Clear target
          </button>
        </div>
      )}
      {!actorId.trim() && (
        <EmptyState
          icon={<UserRound size={22} />}
          title="Login required for submission"
          body="You can draft the suggestion here, but submitting it for review requires a registered account."
        />
      )}
      <div className="form-grid">
        <label>
          <span>What are you sending?</span>
          <select value={type} onChange={(event) => setType(event.target.value)}>
            <option value="add_fact">New fact</option>
            <option value="correct_fact">Correction</option>
            <option value="dispute_fact">Possible problem</option>
            <option value="add_document">Document</option>
            <option value="add_link">Source link</option>
            <option value="add_photo">Photo</option>
            <option value="add_media_metadata">Media details</option>
            <option value="comment">General note</option>
          </select>
        </label>
        <label>
          <span>Page field</span>
          <select value={field} onChange={(event) => setField(event.target.value)}>
            {draftFieldMissing && <option value={field}>{friendlyLabel(field)}</option>}
            {organ.facts.map((fact) => <option key={fact.key} value={fact.key}>{fact.label}</option>)}
          </select>
        </label>
      </div>
      <label>
        <span>Suggested value</span>
        <input value={value} onChange={(event) => setValue(event.target.value)} placeholder="New or corrected value" />
      </label>
      <label>
        <span>Source link</span>
        <input value={evidenceUrl} onChange={(event) => setEvidenceUrl(event.target.value)} placeholder="https://..." />
      </label>
      {attachmentPreview && (
        <div className="contribution-attachment-preview">
          <strong>{attachmentPreview.label}</strong>
          <span>{attachmentPreview.detail}</span>
        </div>
      )}
      <label>
        <span>Note for reviewers</span>
        <textarea value={comment} onChange={(event) => setComment(event.target.value)} placeholder="What should reviewers know?" />
      </label>
      <button type="submit" className="primary-action"><Send size={16} /> Submit suggestion</button>
      {status && <p className="form-status">{status}</p>}
    </form>
  );
}

function contributionAttachmentPreview(type: string, evidenceUrl: string): { label: string; detail: string } | null {
  const hasUrl = Boolean(evidenceUrl.trim());
  if (type === "add_document") {
    return {
      label: "Document for review",
      detail: hasUrl ? "Reviewers will check the document link before adding it to the page." : "Add a document link so reviewers know what to inspect.",
    };
  }
  if (type === "add_photo") {
    return {
      label: "Photo for review",
      detail: hasUrl ? "Reviewers will check the photo link before adding it to the page." : "Add a photo link so reviewers know what to inspect.",
    };
  }
  if (type === "add_link" || hasUrl) {
    return {
      label: "Source link for review",
      detail: "Reviewers will inspect the link before using it on the public page.",
    };
  }
  if (type === "add_media_metadata") {
    return {
      label: "Media details for review",
      detail: "Reviewers will compare these details with existing media on the page.",
    };
  }
  return null;
}

function ContributeSection({ actorId, selectedOrgan, onActorIdChange, onBrowse }: { actorId: string; selectedOrgan: OrganDetail | null; onActorIdChange: (value: string) => void; onBrowse: () => void }) {
  return (
    <section className="entity-section" id="contribute" tabIndex={-1}>
      <SectionHead eyebrow="Contribute" title="Help improve an organ page" detail="Send corrections, source links, photos, documents, or notes for review." />
      {selectedOrgan ? (
        <ContributionComposer actorId={actorId} organ={selectedOrgan} onActorIdChange={onActorIdChange} onSubmitted={() => undefined} />
      ) : (
        <section className="contribution-start">
          <div className="empty-state-icon"><MessageSquarePlus size={22} /></div>
          <div>
            <h3>Open an organ first</h3>
            <p>Open an organ page and choose Contribute there. This keeps every correction, source link, photo, document, or note attached to the right record for review.</p>
            <button type="button" onClick={onBrowse}>Find an organ to improve</button>
          </div>
        </section>
      )}
    </section>
  );
}

