      const openSiteGroup = (
        siteGroupId: string,
        properties: Record<string, unknown>,
        layerId: string,
      ) => {
        const coordinateFallback = layerId === "modavis-locality-fallback-places-v1"
          || properties.coordinateFallback === true;
        const entityCount = Number(properties.entityCount ?? 1);
        setSelectedSiteGroupId(siteGroupId);
        setSelectedSiteGroupProperties({
          ...properties,
          entityCount: Number.isFinite(entityCount) ? entityCount : 1,
          coordinateFallback,
          coordinatePrecision: properties.coordinatePrecision
            || (coordinateFallback ? "locality" : "venue"),
        });
        setSiteGroupOffset(0);
        const pageUrl = new URL(window.location.href);
        pageUrl.searchParams.set("group", siteGroupId);
        window.history.replaceState(window.history.state, "", pageUrl);
      };
      const siteGroupId = typeof featureProperties.siteGroupId === "string"
        ? featureProperties.siteGroupId
        : typeof hit?.featureId === "string" && hit.featureId.startsWith("mapsite:")
          ? hit.featureId
          : "";
